2:     import { PDFDocument, PDFFont, StandardFonts } from "pdf-lib";
3:     import fontkit from "@pdf-lib/fontkit";
4:     import type { TextRunObject, NewTextObject } from "./types";
5: 
6:     export interface ResolvedFont {
7:     font: PDFFont;
8:     widthOfTextAtSize: (text: string, size: number) => number;
9:     substituted: boolean;
10:     face: string;
11:     }
12: 
13:     export function hexToRgbTriplet(hex: string): [number, number, number] {
14:     const clean = hex.replace("#", "");
15:     const n = parseInt(clean, 16);
16: 
17:     return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
18:     }
19: 
20:     export function needsNoto(text: string): boolean {
21:     for (let i = 0; i < text.length; i++) {
22:         if (text.charCodeAt(i) > 0xff) return true;
23:     }
24: 
25:     return false;
26:     }
27: 
28:     /** Maps standard font families to PDF standard fonts and their style variants. */
29:     function standardFontFor(
30:     family: string,
31:     bold: boolean,
32:     italic: boolean,
33:     ): (typeof StandardFonts)[keyof typeof StandardFonts] {
34:     const f = family.toLowerCase();
35: 
36:     if (
37:         f.includes("times") ||
38:         f.includes("georgia") ||
39:         f.includes("garamond") ||
40:         f.includes("cambria")
41:     ) {
42:         if (bold && italic) return StandardFonts.TimesRomanBoldItalic;
43:         if (bold) return StandardFonts.TimesRomanBold;
44:         if (italic) return StandardFonts.TimesRomanItalic;
45: 
46:         return StandardFonts.TimesRoman;
47:     }
48: 
49:     if (f.includes("courier")) {
50:         if (bold && italic) return StandardFonts.CourierBoldOblique;
51:         if (bold) return StandardFonts.CourierBold;
52:         if (italic) return StandardFonts.CourierOblique;
53: 
54:         return StandardFonts.Courier;
55:     }
56: 
57:     if (bold && italic) return StandardFonts.HelveticaBoldOblique;
58:     if (bold) return StandardFonts.HelveticaBold;
59:     if (italic) return StandardFonts.HelveticaOblique;
60: 
61:     return StandardFonts.Helvetica;
62:     }
63: 
64:     /** Custom font files expected in the public/fonts directory. */
65:     const CUSTOM_FONT_FILE: Record<string, string> = {
66:     Roboto: "Roboto-Regular",
67:     "Open Sans": "OpenSans-Regular",
68:     Lato: "Lato-Regular",
69:     Montserrat: "Montserrat-Regular",
70:     Poppins: "Poppins-Regular",
71:     "Noto Sans": "NotoSans-Regular",
72:     };
73: 
74:     /** Resolves a font file from the public directory and embeds it in the PDF. */
75:     async function embedCustomFont(
76:     doc: PDFDocument,
77:     fileName: string,
78:     ): Promise<PDFFont> {
79:     doc.registerFontkit(fontkit);
80: 
81:     const response = await fetch(`/fonts/${fileName}.ttf`);
82: 
83:     if (!response.ok) {
84:         throw new Error(`Font file not found: ${fileName}.ttf`);
85:     }
86: 
87:     const bytes = await response.arrayBuffer();
88: 
89:     return doc.embedFont(bytes, { subset: true });
90:     }
91: 
92:     export async function resolveFontForRun(
93:     doc: PDFDocument,
94:     input: {
95:         fontFamily: string;
96:         bold: boolean;
97:         italic: boolean;
98:         text: string;
99:     },
100:     ): Promise<ResolvedFont> {
101:     const { text, bold, italic, fontFamily } = input;
102: 
103:     // Use Noto Sans for text that may require extended Unicode coverage.
104:     if (needsNoto(text)) {
105:         try {
106:         const font = await embedCustomFont(doc, "NotoSans-Regular");
107: 
108:         return {
109:             font,
110:             widthOfTextAtSize: (value, size) => font.widthOfTextAtSize(value, size),
111:             substituted: fontFamily !== "Noto Sans" || bold || italic,
112:             face: "Noto Sans",
113:         };
114:         } catch {
115:         const font = await doc.embedFont(
116:             standardFontFor("Helvetica", false, false),
117:         );
118: 
119:         return {
120:             font,
121:             widthOfTextAtSize: (value, size) => font.widthOfTextAtSize(value, size),
122:             substituted: true,
123:             face: "Helvetica (fallback)",
124:         };
125:         }
126:     }
127: 
128:     // Try to embed a custom font when a matching file is configured.
129:     const customFile = CUSTOM_FONT_FILE[fontFamily];
130: 
131:     if (customFile) {
132:         try {
133:         const styleSuffix =
134:             bold && italic
135:             ? "-BoldItalic"
136:             : bold
137:                 ? "-Bold"
138:                 : italic
139:                 ? "-Italic"
140:                 : "";
141: 
142:         const fileName = `${customFile.replace(/-Regular$/, "")}${styleSuffix || "-Regular"}`;
143:         const font = await embedCustomFont(doc, fileName);
144: 
145:         return {
146:             font,
147:             widthOfTextAtSize: (value, size) => font.widthOfTextAtSize(value, size),
148:             substituted: false,
149:             face: fontFamily,
150:         };
151:         } catch {
152:         // If the requested custom font file is unavailable, try its regular face.
153:         try {
154:             const font = await embedCustomFont(doc, customFile);
155: 
156:             return {
157:             font,
158:             widthOfTextAtSize: (value, size) =>
159:                 font.widthOfTextAtSize(value, size),
160:             substituted: bold || italic,
161:             face: fontFamily,
162:             };
163:         } catch {
164:             const font = await doc.embedFont(
165:             standardFontFor("Helvetica", bold, italic),
166:             );
167: 
168:             return {
169:             font,
170:             widthOfTextAtSize: (value, size) =>
171:                 font.widthOfTextAtSize(value, size),
172:             substituted: true,
173:             face: "Helvetica (fallback)",
174:             };
175:         }
176:         }
177:     }
178: 
179:     // Use PDF standard fonts for families without a configured custom font file.
180:     const standardFont = standardFontFor(fontFamily, bold, italic);
181:     const font = await doc.embedFont(standardFont);
182: 
183:     const usesFallback =
184:         !fontFamily.toLowerCase().includes("helvetica") &&
185:         !fontFamily.toLowerCase().includes("arial") &&
186:         !fontFamily.toLowerCase().includes("times") &&
187:         !fontFamily.toLowerCase().includes("courier");
188: 
189:     return {
190:         font,
191:         widthOfTextAtSize: (value, size) => font.widthOfTextAtSize(value, size),
192:         substituted: usesFallback,
193:         face: usesFallback ? `${fontFamily} (standard fallback)` : fontFamily,
194:     };
195:     }
196: 
197:     export async function resolveFontForTextRun(
198:     doc: PDFDocument,
199:     run: TextRunObject,
200:     ): Promise<ResolvedFont> {
201:     return resolveFontForRun(doc, {
202:         fontFamily: run.fontFamily,
203:         bold: run.bold,
204:         italic: run.italic,
205:         text: run.text,
206:     });
207:     }
208: 
209:     export async function resolveFontForNewText(
210:     doc: PDFDocument,
211:     obj: NewTextObject,
212:     ): Promise<ResolvedFont> {
213:     return resolveFontForRun(doc, {
214:         fontFamily: obj.fontFamily,
215:         bold: obj.bold,
216:         italic: obj.italic,
217:         text: obj.text,
218:     });
219:     }

