  objects: Record<string, PDFObject>;
  pageObjectIds: string[][];
  zoom: number;
  currentPage: number;
  grid: GridSettings;
  overlays: OverlaySettings; // Added for persistence
  savedAt: number;
  /** Page uids whose text/images were already extracted (so deletes stick). */
  extractedUids?: string[];
}

