import { POST } from "../src/app/api/pdf/from-html/route.ts";
import { NextRequest } from "next/server";
import { PDFDocument } from "pdf-lib";

test("P0-2: /api/pdf/from-html route security and rendering", async (t) => {
  await t.test("Rejects missing or invalid body with 400", async () => {
    const req = new NextRequest("http://localhost:3000/api/pdf/from-html", {
      method: "POST",
      body: JSON.stringify({}),
      headers: { "Content-Type": "application/json" },
    });
    const res = await POST(req);
    assert.equal(res.status, 400);
    const data = await res.json();
    assert.ok(data.error.includes("html"));
  });

  await t.test("Rejects payloads larger than 2MB with 413", async () => {
    const bigHtml = "<div>" + "A".repeat(2_000_001) + "</div>";
    const req = new NextRequest("http://localhost:3000/api/pdf/from-html", {
      method: "POST",
      body: JSON.stringify({ html: bigHtml }),
      headers: { "Content-Type": "application/json" },
    });
    const res = await POST(req);
    assert.equal(res.status, 413);
  });

  await t.test("Renders valid HTML to a loadable PDF without executing network requests", async () => {
    const safeHtml = `
      <!DOCTYPE html>
      <html>
        <head><title>Test</title></head>
        <body>
          <h1>Security Test</h1>
          <p>Local content rendered cleanly.</p>
          <!-- SSRF attempt that must be blocked by route filter -->
          <img src="http://127.0.0.1:9999/malicious" onerror="window.pwned=true" />
        </body>
      </html>
    `;
    const req = new NextRequest("http://localhost:3000/api/pdf/from-html", {
      method: "POST",
      body: JSON.stringify({ html: safeHtml }),
      headers: { "Content-Type": "application/json" },
    });
    const res = await POST(req);
    assert.equal(res.status, 200);
    assert.equal(res.headers.get("Content-Type"), "application/pdf");
    const bytes = await res.arrayBuffer();
    assert.ok(bytes.byteLength > 0, "PDF bytes returned");

    const doc = await PDFDocument.load(bytes);
    assert.ok(doc.getPageCount() >= 1, "PDF is valid and loadable");
  });
});

