// src/lib/rate-limit.ts
import { NextRequest, NextResponse } from "next/server";

interface RateLimitRecord {
  tokens: number;
  lastRefill: number;
}

interface RateLimitOptions {
  /** Maximum burst capacity (tokens). Default: 20 */
  capacity?: number;
  /** Window duration in milliseconds. Default: 60,000ms (1 minute) */
  windowMs?: number;
}

/**
 * In-memory token bucket rate limiter keyed by client IP.
 * NOTE FOR PRODUCTION: In multi-server or serverless cluster environments,
 * replace this in-memory Map with a distributed shared store (e.g. Redis or Upstash).
 */
const ipStore = new Map<string, RateLimitRecord>();

// Cleanup stale records periodically (every 5 minutes)
if (typeof setInterval !== "undefined") {
  const cleanupTimer = setInterval(() => {
    const now = Date.now();
    for (const [ip, record] of ipStore.entries()) {
      if (now - record.lastRefill > 5 * 60 * 1000) {
        ipStore.delete(ip);
      }
    }
  }, 5 * 60 * 1000);
  if (cleanupTimer.unref) {
    cleanupTimer.unref();
  }
}

/**
 * Extracts client IP from standard proxy headers or socket remote address.
 */
export function getClientIp(req: NextRequest): string {
  const forwarded = req.headers.get("x-forwarded-for");
  if (forwarded) {
    const first = forwarded.split(",")[0]?.trim();
    if (first) return first;
  }
  const realIp = req.headers.get("x-real-ip");
  if (realIp) return realIp.trim();

  return "127.0.0.1";
}

/**
 * Checks rate limit for the request.
 * Returns null if allowed, or a 429 NextResponse if rate limit exceeded.
 */
export function checkRateLimit(
  req: NextRequest,
  options: RateLimitOptions = {},
): NextResponse | null {
  const capacity = options.capacity ?? 20;
  const windowMs = options.windowMs ?? 60_000;
  const refillRatePerMs = capacity / windowMs;

  const ip = getClientIp(req);
  const now = Date.now();

  let record = ipStore.get(ip);
  if (!record) {
    record = { tokens: capacity, lastRefill: now };
    ipStore.set(ip, record);
  } else {
    const elapsed = now - record.lastRefill;
    record.tokens = Math.min(capacity, record.tokens + elapsed * refillRatePerMs);
    record.lastRefill = now;
  }

  if (record.tokens < 1) {
    const waitMs = Math.ceil((1 - record.tokens) / refillRatePerMs);
    return NextResponse.json(
      { error: "Too many requests. Please slow down and try again later." },
      {
        status: 429,
        headers: {
          "Retry-After": String(Math.max(1, Math.ceil(waitMs / 1000))),
          "X-RateLimit-Limit": String(capacity),
          "X-RateLimit-Remaining": "0",
        },
      },
    );
  }

  record.tokens -= 1;
  return null;
}

import { NextRequest, NextResponse } from "next/server";
import { chromium } from "playwright";
import { checkRateLimit } from "@/lib/rate-limit";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
export const maxDuration = 60;

class AsyncSemaphore {
  private current = 0;
  private readonly queue: Array<() => void> = [];

  constructor(private readonly max: number) {}

  async acquire(): Promise<void> {
    if (this.current < this.max) {
      this.current++;
      return;
    }
    return new Promise<void>((resolve) => {
      this.queue.push(resolve);
    });
  }

  release(): void {
    this.current--;
    const next = this.queue.shift();
    if (next) {
      this.current++;
      next();
    }
  }
}

// Semaphore to limit concurrent browser instances
const browserSemaphore = new AsyncSemaphore(2);

const MAX_HTML_LENGTH = 2_000_000; // 2MB

export async function POST(req: NextRequest) {
  const rateLimitResponse = checkRateLimit(req);
  if (rateLimitResponse) return rateLimitResponse;

  let body: { html?: unknown };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json(
      { error: "Invalid JSON request body" },
      { status: 400 },
    );
  }

  if (typeof body.html !== "string" || body.html.trim().length === 0) {
    return NextResponse.json(
      { error: "Field 'html' is required and must be a non-empty string" },
      { status: 400 },
    );
  }

  if (body.html.length > MAX_HTML_LENGTH) {
    return NextResponse.json(
      { error: `HTML payload exceeds maximum allowed size (${MAX_HTML_LENGTH} bytes)` },
      { status: 413 },
    );
  }

  await browserSemaphore.acquire();
  let browser;

  try {
    browser = await chromium.launch({
      headless: true,
      args: ["--no-sandbox", "--disable-setuid-sandbox"],
    });

    const context = await browser.newContext({
      javaScriptEnabled: false, // Prevent JS execution (XSS/SSRF mitigations)
    });

    const page = await context.newPage();
    page.setDefaultTimeout(15_000);

    // Block all outbound network and local file requests except inline data/about URLs
    await page.route("**/*", (route) => {
      const url = route.request().url();
      if (url.startsWith("data:") || url.startsWith("about:")) {
        return route.continue();
      }
      return route.abort("blockedbyclient");
    });

    await page.setContent(body.html, {
      waitUntil: "load",
      timeout: 15_000,
    });

    const pdf = await page.pdf({
      format: "A4",
      printBackground: true,
      margin: { top: "1in", right: "1in", bottom: "1in", left: "1in" },
    });

    return new NextResponse(pdf as unknown as Uint8Array<ArrayBuffer>, {
      status: 200,
      headers: {
        "Content-Type": "application/pdf",
        "Cache-Control": "no-store",
      },
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : "PDF rendering failed";
    return NextResponse.json({ error: message }, { status: 500 });
  } finally {
    if (browser) {
      await browser.close().catch(() => {});
    }
    browserSemaphore.release();
  }
}

import { NextRequest, NextResponse } from "next/server";
import { writeFile, readFile, rm, mkdtemp, access } from "fs/promises";
import { execFile } from "child_process";
import { promisify } from "util";
import { join } from "path";
import { tmpdir } from "os";
import { pathToFileURL } from "url";
import { checkRateLimit } from "@/lib/rate-limit";

const runExecFile = promisify(execFile);

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
export const maxDuration = 60;

const MAX_HTML_LENGTH = 2_000_000; // 2MB cap

async function findSoffice(): Promise<string> {
  if (process.env.SOFFICE_PATH) return process.env.SOFFICE_PATH;
  if (process.platform === "win32") {
    for (const c of [
      "C:\\Program Files\\LibreOffice\\program\\soffice.exe",
      "C:\\Program Files (x86)\\LibreOffice\\program\\soffice.exe",
    ]) {
      try {
        await access(c);
        return c;
      } catch {}
    }
  }
  return "soffice";
}

export async function POST(req: NextRequest) {
  const rateLimitResponse = checkRateLimit(req);
  if (rateLimitResponse) return rateLimitResponse;

  let body: { html?: unknown };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json(
      { error: "Invalid JSON request body" },
      { status: 400 },
    );
  }

  if (typeof body.html !== "string" || body.html.trim().length === 0) {
    return NextResponse.json(
      { error: "Field 'html' is required and must be a non-empty string" },
      { status: 400 },
    );
  }

  if (body.html.length > MAX_HTML_LENGTH) {
    return NextResponse.json(
      { error: `HTML payload exceeds maximum allowed size (${MAX_HTML_LENGTH} bytes)` },
      { status: 413 },
    );
  }

  let workDir = "";
  try {
    workDir = await mkdtemp(join(tmpdir(), "filekit-docx-"));
    const htmlPath = join(workDir, "input.html");
    const docxPath = join(workDir, "input.docx");
    const profileDir = join(workDir, "profile");

    await writeFile(htmlPath, body.html, "utf-8");

    const sofficeBin = await findSoffice();
    const profileUrl = pathToFileURL(profileDir).href;

    await runExecFile(
      sofficeBin,
      [
        `-env:UserInstallation=${profileUrl}`,
        "--headless",
        "--norestore",
        "--convert-to",
        'docx:MS Word 2007 XML',
        "--outdir",
        workDir,
        htmlPath,
      ],
      { timeout: 45_000 },
    );

    const buffer = await readFile(docxPath);

    return new NextResponse(buffer, {
      status: 200,
      headers: {
        "Content-Type":
          "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "Content-Disposition": 'attachment; filename="document.docx"',
        "Cache-Control": "no-store",
      },
    });
  } catch (err) {
    console.error("DOCX export failed:", err);
    return NextResponse.json(
      { error: "DOCX export failed. Ensure LibreOffice is installed and SOFFICE_PATH is set if needed." },
      { status: 500 },
    );
  } finally {
    if (workDir) {
      await rm(workDir, { recursive: true, force: true }).catch(() => {});
    }
  }
}

import { NextRequest, NextResponse } from "next/server";
import { docxToPdf } from "@/lib/convert-server";
import { checkRateLimit } from "@/lib/rate-limit";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
export const maxDuration = 180;

export async function POST(req: NextRequest) {
  const rateLimitResponse = checkRateLimit(req);
  if (rateLimitResponse) return rateLimitResponse;

  try {
    const file = (await req.formData()).get("file");
    if (!(file instanceof File))
      return NextResponse.json({ error: "file required" }, { status: 400 });
    if (file.size > 100 * 1024 * 1024)
      return NextResponse.json(
        { error: "File too large (max 100 MB)" },
        { status: 413 },
      );
    const buf = Buffer.from(await file.arrayBuffer());
    if (!buf.subarray(0, 4).equals(Buffer.from([0x50, 0x4b, 0x03, 0x04])))
      return NextResponse.json(
        { error: "Not a valid DOCX file" },
        { status: 400 },
      );
    const out = await docxToPdf(buf);
    return new NextResponse(new Uint8Array(out), {
      status: 200,
      headers: {
        "Content-Type": "application/pdf",
        "Cache-Control": "no-store",
      },
    });
  } catch (err) {
    console.error("docx-to-pdf failed:", err);
    const msg = err instanceof Error ? err.message : "Conversion failed";
    return NextResponse.json({ error: msg.slice(0, 300) }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { pdfToDocx } from "@/lib/convert-server";
import { checkRateLimit } from "@/lib/rate-limit";

export const runtime = "nodejs";
