import { NextRequest, NextResponse } from "next/server";
import { spawn } from "child_process";
import { getFfmpegPath, getQpdfPath } from "@/lib/media-binaries";
import { AVAILABLE_TOOL_COUNT } from "@/lib/tools-registry";
import { checkRateLimit } from "@/lib/rate-limit";

export const dynamic = "force-dynamic";

function canRun(bin: string, args: string[]): Promise<boolean> {
  return new Promise((resolve) => {
    const child = spawn(bin, args, { windowsHide: true });
    child.on("error", () => resolve(false));
    child.on("close", (code) => resolve(code === 0 || code === 1));
    setTimeout(() => {
      try {
        child.kill();
      } catch {
        /* ignore */
      }
      resolve(false);
    }, 4000);
  });
}

export async function GET(req: NextRequest) {
  const rateLimitResponse = checkRateLimit(req, { capacity: 60, windowMs: 60_000 });
  if (rateLimitResponse) return rateLimitResponse;

  const ffmpeg = getFfmpegPath();
  const qpdf = getQpdfPath();
  const ffmpegOk = await canRun(ffmpeg, ["-version"]);
  const qpdfOk = await canRun(qpdf, ["--version"]);
  return NextResponse.json({
    ok: true,
    tools: AVAILABLE_TOOL_COUNT,
    ffmpeg: { path: ffmpeg, available: ffmpegOk },
    qpdf: { path: qpdf, available: qpdfOk },
  });
}

import { spawn } from "node:child_process";

async function testRateLimit() {
  const server = spawn("npx.cmd", ["next", "start", "-p", "3007"], {
    stdio: ["ignore", "pipe", "pipe"],
    shell: true,
  });

  server.stdout.on("data", (d) => process.stdout.write(d));
  server.stderr.on("data", (d) => process.stderr.write(d));

  for (let i = 0; i < 30; i++) {
    try {
      const res = await fetch("http://127.0.0.1:3007/api/health");
      if (res.ok) break;
    } catch {}
    await new Promise((r) => setTimeout(r, 500));
  }

  console.log("\n=== Testing Rate Limiting on API routes ===\n");

  // Test bursting 25 requests to /api/docx/export
  let statuses = [];
  for (let i = 0; i < 25; i++) {
    const res = await fetch("http://127.0.0.1:3007/api/docx/export", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({}),
    });
    statuses.push(res.status);
    if (res.status === 429) {
      const json = await res.json();
      console.log(`Request #${i + 1} blocked by rate limiter: Status 429`, json, "Retry-After:", res.headers.get("Retry-After"));
      break;
    }
  }

  const okCount = statuses.filter((s) => s === 400).length;
  const blockedCount = statuses.filter((s) => s === 429).length;
  console.log(`Summary: ${okCount} requests processed, ${blockedCount} requests rate-limited (429).`);

  server.kill("SIGKILL");
  process.exit(0);
}

testRateLimit();

