1: // src/lib/pdf-editor/history.ts
2: // Ring-buffer undo/redo. The store holds the current snapshot of the pieces
3: // of state we care about (objects, page ops, page info); history stores
4: // immutable references to those pieces, not the whole store.
5: //
6: // We deliberately store references (structural sharing) — the reducer in the
7: // store always produces new top-level objects when mutating, so history
8: // entries never alias each other's contents.
9: 
10: import type { PageInfo, PDFObject, PageOp, GridSettings } from "./types";
11: 
12: export const HISTORY_LIMIT = 100;
13: 
14: export interface HistorySnapshot {
15: /** Objects keyed by id, in their state at that point in time. */
16: objects: Record<string, PDFObject>;
17: /** Per page, the ordered list of object ids (bottom → top). */
18: pageObjectIds: string[][];
19: /** Page geometry in effect at that point in time. */
20: pages: PageInfo[];
21: /** Page-level operations queued for export. */
22: pageOps: PageOp[];
23: /** Optional label for the UI ("Added text", "Moved image", …). */
24: label?: string;
25: }
26: 
27: export interface HistoryState {
28: entries: HistorySnapshot[];
29: index: number; // points at the "current" snapshot
30: }
31: 
32: export function createHistory(initial: HistorySnapshot): HistoryState {
33: return { entries: [initial], index: 0 };
34: }
35: 
36: /**
37:  * Push a new snapshot. Any redo entries past `index` are discarded.
38:  * If the new snapshot is deep-equal to the current one, it is ignored so
39:  * that no-op actions don't spam the buffer.
40:  */
41: export function pushSnapshot(
42: state: HistoryState,
43: next: HistorySnapshot,
44: ): HistoryState {
45: const current = state.entries[state.index];
46: if (current && snapshotsEqual(current, next)) return state;
47: 
48: const trimmed = state.entries.slice(0, state.index + 1);
49: trimmed.push(next);
50: const overflow = Math.max(0, trimmed.length - HISTORY_LIMIT);
51: const entries = overflow > 0 ? trimmed.slice(overflow) : trimmed;
52: const index = entries.length - 1;
53: return { entries, index };
54: }
55: 
56: export function canUndo(state: HistoryState): boolean {
57: return state.index > 0;
58: }
59: 
60: export function canRedo(state: HistoryState): boolean {
61: return state.index < state.entries.length - 1;
62: }
63: 
64: /** Snapshot the caller should restore when the user hits Ctrl+Z. */
65: export function undoTarget(state: HistoryState): HistorySnapshot | null {
66: if (!canUndo(state)) return null;
67: return state.entries[state.index - 1] ?? null;
68: }
69: 
70: /** Snapshot the caller should restore when the user hits Ctrl+Y. */
71: export function redoTarget(state: HistoryState): HistorySnapshot | null {
72: if (!canRedo(state)) return null;
73: return state.entries[state.index + 1] ?? null;
74: }
75: 
76: /** Move the pointer back one entry. Callers restore the returned snapshot. */
77: export function stepBack(state: HistoryState): {
78: state: HistoryState;
79: snapshot: HistorySnapshot | null;
80: } {
81: if (!canUndo(state)) return { state, snapshot: null };
82: const nextIndex = state.index - 1;
83: return {
84:     state: { entries: state.entries, index: nextIndex },
85:     snapshot: state.entries[nextIndex],
86: };
87: }
88: 
89: /** Move the pointer forward one entry. */
90: export function stepForward(state: HistoryState): {
91: state: HistoryState;
92: snapshot: HistorySnapshot | null;
93: } {
94: if (!canRedo(state)) return { state, snapshot: null };
95: const nextIndex = state.index + 1;
96: return {
97:     state: { entries: state.entries, index: nextIndex },
98:     snapshot: state.entries[nextIndex],
99: };
100: }
101: 
102: /**
103:  * Cheap equality. Compares reference identity per component:
104:  *  - objects: top-level map identity + per-id object identity
105:  *  - pageObjectIds: top-level array identity + per-page array identity
106:  *  - pages: array identity + per-page object identity
107:  *  - pageOps: array identity + per-op object identity
108:  * Because the store reducer always creates new containers when mutating,
109:  * reference identity is enough. If nothing was actually mutated (same refs),
110:  * it's a no-op.
111:  */
112: export function snapshotsEqual(
113: a: HistorySnapshot,
114: b: HistorySnapshot,
115: ): boolean {
116: if (a === b) return true;
117: if (a.objects !== b.objects) {
118:     const ak = Object.keys(a.objects);
119:     const bk = Object.keys(b.objects);
120:     if (ak.length !== bk.length) return false;
121:     for (const k of ak) {
122:     if (!(k in b.objects)) return false;
123:     if (a.objects[k] !== b.objects[k]) return false;
124:     }
125: }
126: if (a.pageObjectIds !== b.pageObjectIds) {
127:     if (a.pageObjectIds.length !== b.pageObjectIds.length) return false;
128:     for (let i = 0; i < a.pageObjectIds.length; i++) {
129:     if (a.pageObjectIds[i] !== b.pageObjectIds[i]) return false;
130:     }
131: }
132: if (a.pages !== b.pages) {
133:     if (a.pages.length !== b.pages.length) return false;
134:     for (let i = 0; i < a.pages.length; i++) {
135:     if (a.pages[i] !== b.pages[i]) return false;
136:     }
137: }
138: if (a.pageOps !== b.pageOps) {
139:     if (a.pageOps.length !== b.pageOps.length) return false;
140:     for (let i = 0; i < a.pageOps.length; i++) {
141:     if (a.pageOps[i] !== b.pageOps[i]) return false;
142:     }
143: }
144: return true;
145: }
146: 
147: /**
148:  * Extract a fresh `HistorySnapshot` from the current store shape. Kept here
149:  * so the store can call it without importing itself.
150:  */
151: export function snapshotFromState(args: {
152: objects: Record<string, PDFObject>;
153: pageObjectIds: string[][];
154: pages: PageInfo[];
155: pageOps: PageOp[];
156: label?: string;
157: }): HistorySnapshot {
158: return {
159:     objects: args.objects,
160:     pageObjectIds: args.pageObjectIds,
161:     pages: args.pages,
162:     pageOps: args.pageOps,
163:     label: args.label,
164: };
165: }
166: 
167: /**
168:  * Initial grid settings used both by the store and by the grid dialog.
169:  * Placed in history.ts (not grid-presets.ts) so the store can be built
170:  * without importing the presets module (which is client-only).
171:  */
172: export function defaultGridSettings(): GridSettings {
173: return {
174:     styleId: "square",
175:     cellSize: 24,
176:     unit: "px",
177:     rows: null,
178:     columns: null,
179:     lineColor: "#94a3b8",
180:     lineThicknessPx: 1,
181:     opacity: 0.35,
182:     majorEvery: 5,
183:     offsetX: 0,
184:     offsetY: 0,
185:     snap: true,
186:     showContent: true,
187: };
188: }

