1: // src/lib/pdf-editor/autosave.ts
2: // Debounced autosave to IndexedDB. Subscribes to the store and writes a
3: // session snapshot 1.5s after the last commit. Also flushes on unload.
4: 
5: "use client";
6: 
7: import { usePdfEditor } from "./store";
8: import { saveSession, clearSession } from "./idb";
9: 
10: const DEBOUNCE_MS = 1500;
11: let timer: ReturnType<typeof setTimeout> | null = null;
12: let unsubscribe: (() => void) | null = null;
13: let attached = false;
14: 
15: async function flush(): Promise<void> {
16: if (timer) {
17:     clearTimeout(timer);
18:     timer = null;
19: }
20: const s = usePdfEditor.getState();
21: if (!s.dirty || s.status !== "ready" || !s.originalBytes) return;
22: const snap = s.toSessionSnapshot();
23: if (!snap) return;
24: try {
25:     await saveSession(snap);
26:     usePdfEditor.getState().markSaved();
27: } catch (err) {
28:     console.warn("[autosave] save failed", err);
29: }
30: }
31: 
32: function schedule(): void {
33: if (timer) clearTimeout(timer);
34: timer = setTimeout(() => {
35:     timer = null;
36:     void flush();
37: }, DEBOUNCE_MS);
38: }
39: 
40: export function startAutosave(): void {
41: if (attached) return;
42: attached = true;
43: unsubscribe = usePdfEditor.subscribe((state, prev) => {
44:     if (state.dirty && state.dirty !== prev.dirty) {
45:     schedule();
46:     } else if (state.dirty) {
47:     schedule();
48:     }
49: });
50: if (typeof window !== "undefined") {
51:     window.addEventListener("beforeunload", onBeforeUnload);
52: }
53: }
54: 
55: export function stopAutosave(): void {
56: if (unsubscribe) {
57:     unsubscribe();
58:     unsubscribe = null;
59: }
60: if (timer) {
61:     clearTimeout(timer);
62:     timer = null;
63: }
64: attached = false;
65: if (typeof window !== "undefined") {
66:     window.removeEventListener("beforeunload", onBeforeUnload);
67: }
68: }
69: 
70: export async function flushAutosave(): Promise<void> {
71: await flush();
72: }
73: 
74: export async function discardSession(): Promise<void> {
