32:         const db = request.result;
33:         if (!db.objectStoreNames.contains(HANDOFF_STORE)) {
34:             db.createObjectStore(HANDOFF_STORE);
35:         }
36:         if (!db.objectStoreNames.contains(SESSION_STORE)) {
37:             db.createObjectStore(SESSION_STORE);
38:         }
39:         };
40:         request.onsuccess = () => resolve(request.result);
41:         request.onerror = () =>
42:         reject(request.error ?? new Error("IDB open failed"));
43:         request.onblocked = () =>
44:         reject(new Error("IndexedDB upgrade blocked — close other tabs."));
45:     });
