48:     function writeOne<T>(store: string, value: T): Promise<void> {
49:     return openDb().then(
50:         (db) =>
51:         new Promise<void>((resolve, reject) => {
52:             const tx = db.transaction(store, "readwrite");
53:             tx.objectStore(store).put(value, "current");
54:             tx.oncomplete = () => {
55:             db.close();
56:             resolve();
57:             };
58:             tx.onerror = () => {
59:             db.close();
60:             reject(tx.error ?? new Error("IDB write failed"));
61:             };
62:         }),
63:     );
64:     }
65: 
66:     function readOne<T>(store: string): Promise<T | null> {
67:     return openDb().then(
68:         (db) =>
69:         new Promise<T | null>((resolve, reject) => {
70:             const tx = db.transaction(store, "readonly");
71:             const req = tx.objectStore(store).get("current");
72:             req.onsuccess = () => {
73:             db.close();
74:             resolve((req.result as T | undefined) ?? null);
75:             };
76:             req.onerror = () => {
77:             db.close();
78:             reject(req.error ?? new Error("IDB read failed"));
79:             };
80:         }),
81:     );
82:     }
83: 
84:     function deleteOne(store: string): Promise<void> {
85:     return openDb().then(
86:         (db) =>
87:         new Promise<void>((resolve, reject) => {
88:             const tx = db.transaction(store, "readwrite");
89:             tx.objectStore(store).delete("current");
90:             tx.oncomplete = () => {
91:             db.close();
92:             resolve();
93:             };
94:             tx.onerror = () => {
95:             db.close();
96:             reject(tx.error ?? new Error("IDB delete failed"));
97:             };
98:         }),
99:     );
100:     }
