102:     /* ───────────── Handoff (launcher → /pdf-editor) ───────────── */
103: 
104:     export function saveHandoff(
105:     bytes: Uint8Array,
106:     fileName: string,
107:     ): Promise<void> {
108:     const payload: HandoffPayload = {
109:         bytes,
110:         fileName,
111:         createdAt: Date.now(),
112:     };
113:     return writeOne(HANDOFF_STORE, payload);
114:     }
115: 
116:     export function readHandoff(): Promise<HandoffPayload | null> {
117:     return readOne<HandoffPayload>(HANDOFF_STORE);
118:     }
119: 
120:     export function clearHandoff(): Promise<void> {
121:     return deleteOne(HANDOFF_STORE);
122:     }
123: 
124:     /* ───────────── Session snapshot (autosave) ───────────── */
125: 
126:     export function saveSession(snapshot: SessionSnapshot): Promise<void> {
127:     return writeOne(SESSION_STORE, snapshot);
128:     }
129: 
130:     export function readSession(): Promise<SessionSnapshot | null> {
131:     return readOne<SessionSnapshot>(SESSION_STORE);
132:     }
133: 
134:     export function clearSession(): Promise<void> {
135:     return deleteOne(SESSION_STORE);
136:     }

