56: /**
57:  * Build a matrix that maps PDF points (origin bottom-left) to CSS pixels
58:  * (origin top-left) inside a page element.
59:  *
60:  * We use the pdfjs viewport transform at scale=1, rotation=pageRotation.
61:  * Then we apply zoom. This guarantees the overlay matches the canvas
62:  * exactly, because the canvas is rendered with the same viewport.
63:  *
64:  * @param pageInfo - page dimensions and rotation
65:  * @param zoom - current zoom level (1 = 100%)
66:  * @returns Mat2D mapping PDF user space to CSS pixels
67:  */
68: export function pdfToCssMatrix(pageInfo: PageInfo, zoom: number): Mat2D {
69:   // Exact equivalent of pdfjs PageViewport.transform for a viewBox at (0,0).
70:   const { widthPt: W, heightPt: H, rotation } = pageInfo;
71:   const s = zoom;
72:   switch (rotation) {
73:     case 90:
74:       return { a: 0, b: s, c: s, d: 0, e: 0, f: 0 };
75:     case 180:
76:       return { a: -s, b: 0, c: 0, d: s, e: W * s, f: 0 };
77:     case 270:
78:       return { a: 0, b: -s, c: -s, d: 0, e: H * s, f: W * s };
79:     default:
80:       return { a: s, b: 0, c: 0, d: -s, e: 0, f: H * s };
81:   }
82: }
