84: /** Inverse of pdfToCssMatrix. */
85: export function cssToPdfMatrix(pageInfo: PageInfo, zoom: number): Mat2D {
86:   const m = pdfToCssMatrix(pageInfo, zoom);
87:   const det = m.a * m.d - m.b * m.c;
88:   if (det === 0) return identity();
89:   return {
90:     a: m.d / det,
91:     b: -m.b / det,
92:     c: -m.c / det,
93:     d: m.a / det,
94:     e: (m.c * m.f - m.d * m.e) / det,
95:     f: (m.b * m.e - m.a * m.f) / det,
96:   };
97: }
