115: /** Convert a PDF-space rect into a CSS-space rect (positive width/height). */
116: export function pdfRectToCss(
117:   rect: RectPt,
118:   pageInfo: PageInfo,
119:   zoom: number,
120: ): { left: number; top: number; width: number; height: number } {
121:   const m = pdfToCssMatrix(pageInfo, zoom);
122:   const corners = [
123:     apply(m, rect.x, rect.y),
124:     apply(m, rect.x + rect.w, rect.y),
125:     apply(m, rect.x + rect.w, rect.y + rect.h),
126:     apply(m, rect.x, rect.y + rect.h),
127:   ];
128:   const xs = corners.map((c) => c.x);
129:   const ys = corners.map((c) => c.y);
130:   const left = Math.min(...xs);
131:   const top = Math.min(...ys);
132:   const width = Math.max(...xs) - left;
133:   const height = Math.max(...ys) - top;
134:   return { left, top, width, height };
