143:   const m = cssToPdfMatrix(pageInfo, zoom);
144:   const corners = [
145:     apply(m, css.left, css.top),
146:     apply(m, css.left + css.width, css.top),
147:     apply(m, css.left, css.top + css.height),
148:     apply(m, css.left + css.width, css.top + css.height),
