208:   const p2 = { x: p1.x + uy.x * BOX * h, y: p1.y + uy.y * BOX * h };
209:   const p3 = { x: p0.x + uy.x * BOX * h, y: p0.y + uy.y * BOX * h };
210:   const xs = [p0.x, p1.x, p2.x, p3.x];
211:   const ys = [p0.y, p1.y, p2.y, p3.y];
212:   const x = Math.min(...xs);
213:   const y = Math.min(...ys);
214:   return { x, y, w: Math.max(...xs) - x, h: Math.max(...ys) - y };
215: }
