217: /** Turn `rgb(…)` / `#rrggbb` into `#rrggbb`. Falls back to `#000000`. */
218: export function normalizeHexColor(input: string): string {
219:   if (!input) return "#000000";
220:   const s = input.trim();
221:   if (/^#[0-9a-fA-F]{6}$/.test(s)) return s.toLowerCase();
222:   if (/^#[0-9a-fA-F]{3}$/.test(s)) {
223:     const r = s[1];
224:     const g = s[2];
225:     const b = s[3];
226:     return `#${r}${r}${g}${g}${b}${b}`.toLowerCase();
227:   }
228:   const m = s.match(/rgba?\(([^)]+)\)/i);
229:   if (m) {
230:     const parts = m[1].split(",").map((p) => parseFloat(p.trim()));
231:     if (parts.length >= 3) {
232:       const [r, g, b] = parts;
233:       const toHex = (v: number) =>
234:         Math.max(0, Math.min(255, Math.round(v)))
235:           .toString(16)
236:           .padStart(2, "0");
237:       return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
238:     }
239:   }
240:   return "#000000";
241: }

