57:     // FIX: Explicitly type the styles record instead of using `any`
58:     const styles = (content.styles || {}) as Record<
59:         string,
60:         { fontFamily?: string }
61:     >;
62: 
63:     const out: TextRunObject[] = [];
64:     const seen = new Set<string>();
65: 
66:     for (let i = 0; i < items.length; i++) {
67:         const item = items[i];
68:         const text = typeof item.str === "string" ? item.str : "";
69:         if (!text.trim()) continue;
70: 
71:         const rect = pdfjsTextItemToPdfRect({
72:         transform: item.transform,
73:         width: item.width,
74:         height: item.height,
75:         });
76:         if (rect.w <= 0.1 || rect.h <= 0.1) continue;
77: 
78:         // Use pageUid to prevent collisions on duplicated pages
79:         const id = makeRunId(pageUid(pageInfo), i, text);
80:         if (seen.has(id)) continue;
81:         seen.add(id);
