87:         let fontFamily = "Arial";
88:         if (/serif/i.test(fontFamilyStr)) fontFamily = "Times New Roman";
89:         else if (/courier|mono/i.test(fontFamilyStr)) fontFamily = "Courier New";
90: 
91:         const bold = /bold|black|heavy|semibold/i.test(fontFamilyStr);
92:         const italic = /italic|oblique/i.test(fontFamilyStr);
93: 
94:         // 2. Font size from the linear part of the transform matrix
95:         const a = item.transform[0] ?? 1;
96:         const b = item.transform[1] ?? 0;
97:         const c = item.transform[2] ?? 0;
98:         const d = item.transform[3] ?? 1;
99:         const fontSize = Math.max(4, Math.hypot(c, d) || Math.hypot(a, b) || 10);
100: 
101:         const bg = options.sampleBackground
102:         ? options.sampleBackground(rect)
103:         : (options.defaultBackground ?? "#ffffff");
104: 
105:         const run: TextRunObject = {
106:         id,
107:         kind: "text-run",
108:         page: pageInfo.index,
109:         rect,
110:         rotation: 0,
111:         z: out.length,
112:         locked: false,
113:         opacity: 1,
114:         dirty: false,
115:         text,
116:         originalText: text,
117:         sourceFontName: fontFamilyStr || "unknown",
118:         fontFamily,
119:         substituted: false,
120:         fontSize,
121:         bold,
122:         italic,
123:         underline: false,
124:         color: "#000000",
125:         align: "left",
126:         lineHeight: 1.2,
127:         letterSpacing: 0,
128:         backgroundColor: normalizeHexColor(bg),
129:         };
