131:     }
132: 
133:     // Sort for stable visual order: top → bottom, then left → right.
134:     out.sort((p, q) => {
135:         if (Math.abs(q.rect.y - p.rect.y) > 1) return q.rect.y - p.rect.y;
136:         return p.rect.x - q.rect.x;
137:     });
138: 
139:     // Reassign z after sorting so the array order matches the visual order.
140:     return out.map((run, idx) => ({ ...run, z: idx }));
141:     }
