143:     /**
144:      * Merge freshly-extracted runs with any that already exist in the store.
145:      * Existing runs whose ids match a newly-extracted run keep their edited
146:      * state (`dirty`, `text`, style); new runs are added. Runs that no longer
147:      * appear in the PDF (user edited them away) are kept if `dirty` so the
148:      * user can still export them, otherwise dropped.
149:      */
150:     export function reconcileTextRuns(
151:     existing: TextRunObject[],
152:     fresh: TextRunObject[],
153:     ): TextRunObject[] {
154:     const byId = new Map(existing.map((r) => [r.id, r]));
155:     const merged: TextRunObject[] = [];
156:     const used = new Set<string>();
157: 
158:     for (const run of fresh) {
159:         const prior = byId.get(run.id);
160:         if (prior) {
161:         merged.push(prior);
162:         used.add(prior.id);
163:         } else {
164:         merged.push(run);
165:         }
166:     }
167: 
168:     for (const run of existing) {
169:         if (!used.has(run.id) && run.dirty) merged.push(run);
170:     }
171: 
172:     return merged;
173:     }

