  obj,
  editingId,
  setEditingId,
  updateObject,
  isDragging = false,
}: ObjectContentProps) {
  const [draft, setDraft] = useState("");
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);

  const isEditing = editingId === obj.id;

