const fs = require('fs');
const file = 'src/lib/pdf-editor/coords.ts';
let content = fs.readFileSync(file, 'utf8');

const target = `/** Clamp a rect so it stays inside the page box (0..widthPt, 0..heightPt). */
export function clampRectToPage(rect: RectPt, page: PageInfo): RectPt {
  const w = Math.min(rect.w, page.widthPt);
  const h = Math.min(rect.h, page.heightPt);
  const x = Math.max(0, Math.min(rect.x, page.widthPt - w));
  const y = Math.max(0, Math.min(rect.y, page.heightPt - h));
  return { x, y, w, h };
}`;

const replacement = `/** Clamp a rect so it stays inside the page box (0..widthPt, 0..heightPt). */
export function clampRectToPage(rect: RectPt, page: PageInfo): RectPt {
  const w = Math.min(rect.w, page.widthPt);
  const h = Math.min(rect.h, page.heightPt);
  const x = Math.max(0, Math.min(rect.x, page.widthPt - w));
  const y = Math.max(0, Math.min(rect.y, page.heightPt - h));
  return { x, y, w, h };
}

export const clampRect = clampRectToPage;`;

content = content.replace(/\r\n/g, '\n');
if (content.includes(target)) {
  content = content.replace(target, replacement);
  fs.writeFileSync(file, content, 'utf8');
  console.log('Successfully updated coords.ts');
} else {
  console.error('Target not found in coords.ts');
}

