const fs = require('fs');
const file = 'src/components/pdf-editor/ObjectLayer.tsx';
let content = fs.readFileSync(file, 'utf8');

const target = `function ObjectContent({
  obj,
  editingId,
  setEditingId,
  updateObject,
  isDragging = false,
}: ObjectContentProps) {
  const [draft, setDraft] = useState("");
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);

  const isEditing = editingId === obj.id;

  // Initialize draft and select all text when editor opens (dblclick or Enter key)
  useEffect(() => {
    if (isEditing) {
      if (obj.kind === "text-run" || obj.kind === "new-text") {
        setDraft((obj as TextRunObject | NewTextObject).text);
      }
      if (textareaRef.current) {
        textareaRef.current.select();
      }
    }
  }, [isEditing, obj]);`;

const replacement = `function ObjectContent({
  obj,
  editingId,
  setEditingId,
  updateObject,
  isDragging = false,
}: ObjectContentProps) {
  const isEditing = editingId === obj.id;
  const isText = obj.kind === "text-run" || obj.kind === "new-text";
  const textVal = isText ? (obj as TextRunObject | NewTextObject).text : "";
  const [draft, setDraft] = useState(textVal);
  const [prevEditing, setPrevEditing] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);

  // Sync draft during render when editing starts (official React 19 pattern)
  if (isEditing && !prevEditing) {
    setPrevEditing(true);
    setDraft(textVal);
  } else if (!isEditing && prevEditing) {
    setPrevEditing(false);
  }

  // Focus and select all text when editor opens
  useEffect(() => {
    if (isEditing && textareaRef.current) {
      textareaRef.current.select();
    }
  }, [isEditing]);`;

content = content.replace(/\r\n/g, '\n');
if (content.includes(target)) {
  content = content.replace(target, replacement);
  fs.writeFileSync(file, content, 'utf8');
  console.log('Successfully updated ObjectLayer.tsx');
} else {
  console.error('Target not found');
}

