// src/components/preview/types.ts

export interface PreviewEffects {
  /** Rotation in degrees (e.g. 90, 180, 270) */
  rotateDeg?: number;
  /** Flip horizontally */
  flipH?: boolean;
  /** Flip vertically */
  flipV?: boolean;
  /** Brightness percentage (default 100) */
  brightness?: number;
  /** Contrast percentage (default 100) */
  contrast?: number;
  /** Saturation percentage (default 100) */
  saturation?: number;
  /** Grayscale percentage (0 - 100) */
  grayscale?: number;
  /** Target resize width */
  resizeWidth?: number;
  /** Target resize height */
  resizeHeight?: number;
  /** Target output format (png, jpg, webp, etc.) */
  targetFormat?: string;
  /** Quality percentage (0 - 100) */
  quality?: number;
  /** Crop coordinates in percentages (0 - 100) */
  crop?: {
    x: number;
    y: number;
    w: number;
    h: number;
  };
  // PDF Overlays
  watermarkText?: string;
  pageNumbers?: boolean;
  pdfRotation?: number;
}

export type FileCategory =
  | "image"
  | "pdf"
  | "video"
  | "audio"
  | "document"
  | "other";

export interface PreviewPanelProps {
  files: File[];
  effects?: PreviewEffects;
  activeFileIndex?: number;
  onSelectFile?: (index: number) => void;
  className?: string;
  onRemoveFile?: (index: number) => void;
}

// src/components/preview/preview-utils.ts
import type { FileCategory, PreviewEffects } from "./types";

/** Categorize a file by MIME type and filename extension */
export function getFileCategory(file: File): FileCategory {
  const mime = (file.type || "").toLowerCase();
  const name = (file.name || "").toLowerCase();

  if (mime.startsWith("image/") || /\.(png|jpe?g|webp|gif|svg|bmp|avif|ico|tiff?)$/i.test(name)) {
    return "image";
  }
  if (mime === "application/pdf" || name.endsWith(".pdf")) {
    return "pdf";
  }
  if (mime.startsWith("video/") || /\.(mp4|webm|mov|mkv|avi)$/i.test(name)) {
    return "video";
  }
  if (mime.startsWith("audio/") || /\.(mp3|wav|ogg|aac|flac|m4a)$/i.test(name)) {
    return "audio";
  }
  if (
    mime.includes("document") ||
    mime.includes("word") ||
    mime.includes("text") ||
    /\.(docx?|txt|rtf|odt|md)$/i.test(name)
  ) {
    return "document";
  }
  return "other";
}

/** Compute CSS filter and transform strings for instant live image preview */
export function getEffectCss(effects?: PreviewEffects): {
  filter: string;
  transform: string;
  hasEffects: boolean;
} {
  if (!effects) {
    return { filter: "none", transform: "none", hasEffects: false };
  }

  const filters: string[] = [];
  const transforms: string[] = [];

  if (effects.brightness !== undefined && effects.brightness !== 100) {
    filters.push(`brightness(${effects.brightness}%)`);
  }
  if (effects.contrast !== undefined && effects.contrast !== 100) {
    filters.push(`contrast(${effects.contrast}%)`);
  }
  if (effects.saturation !== undefined && effects.saturation !== 100) {
    filters.push(`saturate(${effects.saturation}%)`);
  }
  if (effects.grayscale !== undefined && effects.grayscale > 0) {
    filters.push(`grayscale(${effects.grayscale}%)`);
  }

  if (effects.rotateDeg && effects.rotateDeg % 360 !== 0) {
    transforms.push(`rotate(${effects.rotateDeg}deg)`);
  }
  if (effects.flipH) {
    transforms.push("scaleX(-1)");
  }
  if (effects.flipV) {
    transforms.push("scaleY(-1)");
  }

  const filter = filters.length > 0 ? filters.join(" ") : "none";
  const transform = transforms.length > 0 ? transforms.join(" ") : "none";
  const hasEffects = filter !== "none" || transform !== "none";

  return { filter, transform, hasEffects };
}

/** Compute fit scale ratio ensuring content fits within a container */
export function calculateFitScale(
  containerW: number,
  containerH: number,
  contentW: number,
  contentH: number,
  padding = 16,
): number {
  if (containerW <= 0 || containerH <= 0 || contentW <= 0 || contentH <= 0) {
    return 1;
  }
  const availW = Math.max(1, containerW - padding * 2);
  const availH = Math.max(1, containerH - padding * 2);
  const scaleW = availW / contentW;
  const scaleH = availH / contentH;
  return Math.min(scaleW, scaleH);
}

/** Generate a deterministic cache key for estimated output size */
export function getEstimatedSizeCacheKey(
  fileName: string,
  fileSize: number,
  format?: string,
  quality?: number,
  width?: number,
  height?: number,
): string {
  return `${fileName}_${fileSize}_${format || "orig"}_${quality ?? 85}_${width ?? 0}x${height ?? 0}`;
}

const sizeEstimateCache = new Map<string, number>();

/**
 * Estimate output size by encoding a scaled copy (max 1280px) on an off-screen canvas.
 * Results are cached by option keys to prevent re-encoding.
 */
export async function estimateOutputSize(
  file: File,
  format?: string,
  quality?: number,
  width?: number,
  height?: number,
): Promise<number | null> {
  if (typeof window === "undefined" || !file.type.startsWith("image/")) {
    return null;
  }

  const targetFmt = (format || "jpeg").toLowerCase().replace("jpg", "jpeg");
  const q = (quality ?? 85) / 100;
  const key = getEstimatedSizeCacheKey(file.name, file.size, targetFmt, quality, width, height);

  if (sizeEstimateCache.has(key)) {
    return sizeEstimateCache.get(key)!;
  }

  try {
    const bmp = await createImageBitmap(file);
    const maxDim = 1280;
    let w = width || bmp.width;
    let h = height || bmp.height;

    if (w > maxDim || h > maxDim) {
      const ratio = Math.min(maxDim / w, maxDim / h);
      w = Math.max(1, Math.round(w * ratio));
      h = Math.max(1, Math.round(h * ratio));
    }

    const canvas = document.createElement("canvas");
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      bmp.close();
      return null;
    }

    ctx.drawImage(bmp, 0, 0, w, h);
    bmp.close();

    const mime = `image/${targetFmt === "ico" ? "png" : targetFmt}`;
    const blob = await new Promise<Blob | null>((resolve) =>
      canvas.toBlob(resolve, mime, q),
    );

    if (blob) {
      // Extrapolate ratio if we downscaled from full size
      let estimated = blob.size;
      const originalPixels = (width || bmp.width) * (height || bmp.height);
      const samplePixels = w * h;
      if (originalPixels > samplePixels && samplePixels > 0) {
        const factor = Math.sqrt(originalPixels / samplePixels);
        estimated = Math.round(blob.size * factor);
      }
      sizeEstimateCache.set(key, estimated);
      return estimated;
    }
    return null;
  } catch {
    return null;
  }
}

// src/components/preview/usePreview.ts
"use client";

import { useEffect, useRef, useState, useCallback } from "react";

export interface UsePreviewReturn {
  objectUrl: string | null;
  zoom: number;
  fitMode: "fit" | "100%";
  pan: { x: number; y: number };
  isDragging: boolean;
  showOriginal: boolean;
  setShowOriginal: (show: boolean) => void;
  setFitMode: (mode: "fit" | "100%") => void;
  zoomIn: () => void;
  zoomOut: () => void;
  resetZoom: () => void;
  onPointerDown: (e: React.PointerEvent) => void;
  onPointerMove: (e: React.PointerEvent) => void;
  onPointerUp: (e: React.PointerEvent) => void;
  onWheel: (e: React.WheelEvent) => void;
}

export function usePreview(file: File | null): UsePreviewReturn {
  const [objectUrl, setObjectUrl] = useState<string | null>(null);
  const [zoom, setZoom] = useState<number>(1);
  const [fitMode, setFitMode] = useState<"fit" | "100%">("fit");
  const [pan, setPan] = useState<{ x: number; y: number }>({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState<boolean>(false);
  const [showOriginal, setShowOriginal] = useState<boolean>(false);

  const dragStartRef = useRef<{ x: number; y: number } | null>(null);
  const rafRef = useRef<number | null>(null);

  // Object URL lifecycle: create on file change, always revoke on change & unmount
  useEffect(() => {
    if (!file) {
      setObjectUrl(null);
      return;
    }

    const url = URL.createObjectURL(file);
    setObjectUrl(url);

    // Reset view states for new file
    setZoom(1);
    setFitMode("fit");
    setPan({ x: 0, y: 0 });
    setShowOriginal(false);

    return () => {
      URL.revokeObjectURL(url);
    };
  }, [file]);

  const zoomIn = useCallback(() => {
    setFitMode("100%");
    setZoom((prev) => Math.min(4, +(prev + 0.25).toFixed(2)));
  }, []);

  const zoomOut = useCallback(() => {
    setFitMode("100%");
    setZoom((prev) => Math.max(0.25, +(prev - 0.25).toFixed(2)));
  }, []);

  const resetZoom = useCallback(() => {
    setFitMode("fit");
    setZoom(1);
    setPan({ x: 0, y: 0 });
  }, []);

  const onPointerDown = useCallback((e: React.PointerEvent) => {
    if (e.button !== 0) return; // Left click only
    dragStartRef.current = { x: e.clientX, y: e.clientY };
    setIsDragging(true);
    (e.currentTarget as HTMLElement).setPointerCapture?.(e.pointerId);
  }, []);

  const onPointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!dragStartRef.current || !isDragging) return;
      const dx = e.clientX - dragStartRef.current.x;
      const dy = e.clientY - dragStartRef.current.y;
      dragStartRef.current = { x: e.clientX, y: e.clientY };

      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      rafRef.current = requestAnimationFrame(() => {
        setPan((prev) => ({ x: prev.x + dx, y: prev.y + dy }));
      });
    },
    [isDragging],
  );

  const onPointerUp = useCallback((e: React.PointerEvent) => {
    dragStartRef.current = null;
    setIsDragging(false);
    try {
      (e.currentTarget as HTMLElement).releasePointerCapture?.(e.pointerId);
    } catch {
      // Ignored
    }
  }, []);

  const onWheel = useCallback((e: React.WheelEvent) => {
    if (e.ctrlKey || e.metaKey) {
      e.preventDefault();
      const delta = e.deltaY < 0 ? 0.15 : -0.15;
      setFitMode("100%");
      setZoom((prev) => Math.min(4, Math.max(0.25, +(prev + delta).toFixed(2))));
    }
  }, []);

  return {
    objectUrl,
    zoom,
    fitMode,
    pan,
    isDragging,
    showOriginal,
    setShowOriginal,
    setFitMode,
    zoomIn,
    zoomOut,
    resetZoom,
    onPointerDown,
    onPointerMove,
    onPointerUp,
    onWheel,
  };
}

// src/components/preview/PreviewToolbar.tsx
"use client";

import React from "react";
import {
  ZoomIn,
  ZoomOut,
  Maximize2,
  RotateCcw,
  ChevronLeft,
  ChevronRight,
  Info,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";

interface PreviewToolbarProps {
  zoom: number;
  fitMode: "fit" | "100%";
  onZoomIn: () => void;
  onZoomOut: () => void;
  onResetZoom: () => void;
  onToggleFit: () => void;
  hasEffects?: boolean;
  showOriginal?: boolean;
  onToggleOriginal?: (show: boolean) => void;
  isApproximate?: boolean;
  // PDF page navigation
  currentPage?: number;
  totalPages?: number;
  onPrevPage?: () => void;
  onNextPage?: () => void;
}

export function PreviewToolbar({
  zoom,
  fitMode,
  onZoomIn,
  onZoomOut,
  onResetZoom,
  onToggleFit,
  hasEffects = false,
  showOriginal = false,
  onToggleOriginal,
  isApproximate = false,
  currentPage,
  totalPages,
  onPrevPage,
  onNextPage,
}: PreviewToolbarProps) {
  return (
    <div className="flex items-center justify-between gap-2 px-3 py-2 bg-card/90 backdrop-blur-sm border-b border-border text-xs z-10 flex-wrap">
      {/* Left: Preview badge & approximation note */}
      <div className="flex items-center gap-2">
        <Badge variant="outline" className="text-[10px] uppercase tracking-wider font-semibold">
          Preview
        </Badge>
        {isApproximate && (
          <span className="text-[11px] text-muted-foreground flex items-center gap-1 hidden sm:inline-flex">
            <Info className="w-3 h-3 text-amber-500" />
            Final output may differ slightly
          </span>
        )}
      </div>

      {/* Middle: PDF Page Navigation (if PDF) */}
      {totalPages && totalPages > 1 && (
        <div className="flex items-center gap-1.5 bg-muted/60 px-2 py-0.5 rounded-md border border-border/50">
          <Button
            variant="ghost"
            size="icon"
            className="h-6 w-6"
            onClick={onPrevPage}
            disabled={!currentPage || currentPage <= 1}
            aria-label="Previous Page"
          >
            <ChevronLeft className="w-3.5 h-3.5" />
          </Button>
          <span className="text-[11px] font-mono select-none">
            {currentPage ?? 1} / {totalPages}
          </span>
          <Button
            variant="ghost"
            size="icon"
            className="h-6 w-6"
            onClick={onNextPage}
            disabled={!currentPage || currentPage >= totalPages}
            aria-label="Next Page"
          >
            <ChevronRight className="w-3.5 h-3.5" />
          </Button>
        </div>
      )}

      {/* Right: Before/After & Zoom Controls */}
      <div className="flex items-center gap-1">
        {hasEffects && onToggleOriginal && (
          <div className="inline-flex rounded-md border border-border p-0.5 bg-muted/40 mr-1.5">
            <button
              type="button"
              onClick={() => onToggleOriginal(false)}
              className={`px-2 py-0.5 text-[11px] rounded transition-colors ${
                !showOriginal
                  ? "bg-primary text-primary-foreground font-medium shadow-xs"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              After
            </button>
            <button
              type="button"
              onClick={() => onToggleOriginal(true)}
              className={`px-2 py-0.5 text-[11px] rounded transition-colors ${
                showOriginal
                  ? "bg-primary text-primary-foreground font-medium shadow-xs"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              Before
            </button>
          </div>
        )}

        <Button
          variant="ghost"
          size="icon"
          className="h-6 w-6"
          onClick={onToggleFit}
          title={fitMode === "fit" ? "Switch to 100%" : "Fit to screen"}
          aria-label="Toggle Fit Mode"
        >
          <Maximize2 className="w-3.5 h-3.5" />
        </Button>

        <Button
          variant="ghost"
          size="icon"
          className="h-6 w-6"
          onClick={onZoomOut}
          disabled={zoom <= 0.25}
          title="Zoom out"
          aria-label="Zoom Out"
        >
          <ZoomOut className="w-3.5 h-3.5" />
        </Button>

        <span className="text-[11px] font-mono w-9 text-center select-none">
          {Math.round(zoom * 100)}%
        </span>

        <Button
          variant="ghost"
          size="icon"
          className="h-6 w-6"
          onClick={onZoomIn}
          disabled={zoom >= 4}
          title="Zoom in"
          aria-label="Zoom In"
        >
          <ZoomIn className="w-3.5 h-3.5" />
        </Button>

        <Button
          variant="ghost"
          size="icon"
          className="h-6 w-6"
          onClick={onResetZoom}
          title="Reset zoom"
          aria-label="Reset Zoom"
        >
          <RotateCcw className="w-3.5 h-3.5" />
        </Button>
      </div>
    </div>
  );
}

// src/components/preview/ImagePreview.tsx
"use client";

import React, { useEffect, useState, useMemo, useRef } from "react";
import { formatBytes } from "@/lib/utils";
import type { PreviewEffects } from "./types";
import { getEffectCss, estimateOutputSize } from "./preview-utils";

interface ImagePreviewProps {
  file: File;
  objectUrl: string;
  effects?: PreviewEffects;
  zoom: number;
  pan: { x: number; y: number };
  fitMode: "fit" | "100%";
  showOriginal: boolean;
  isDragging: boolean;
  onPointerDown: (e: React.PointerEvent) => void;
  onPointerMove: (e: React.PointerEvent) => void;
  onPointerUp: (e: React.PointerEvent) => void;
  onWheel: (e: React.WheelEvent) => void;
}

export function ImagePreview({
  file,
  objectUrl,
  effects,
  zoom,
  pan,
  fitMode,
  showOriginal,
  isDragging,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onWheel,
}: ImagePreviewProps) {
  const [dimensions, setDimensions] = useState<{ width: number; height: number } | null>(null);
  const [estimatedSize, setEstimatedSize] = useState<number | null>(null);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  // Measure natural dimensions on image load
  const onImageLoad = (e: React.SyntheticEvent<HTMLImageElement>) => {
    const img = e.currentTarget;
    setDimensions({ width: img.naturalWidth, height: img.naturalHeight });
  };

  // Debounced estimated output size calculation
  useEffect(() => {
    if (timerRef.current) clearTimeout(timerRef.current);

    if (effects?.quality || effects?.targetFormat || effects?.resizeWidth) {
      timerRef.current = setTimeout(async () => {
        const est = await estimateOutputSize(
          file,
          effects?.targetFormat,
          effects?.quality,
          effects?.resizeWidth,
          effects?.resizeHeight,
        );
        setEstimatedSize(est);
      }, 300);
    } else {
      setEstimatedSize(null);
    }

    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [file, effects?.quality, effects?.targetFormat, effects?.resizeWidth, effects?.resizeHeight]);

  const { filter, transform } = useMemo(() => {
    if (showOriginal) {
      return { filter: "none", transform: "none", hasEffects: false };
    }
    return getEffectCss(effects);
  }, [effects, showOriginal]);

  // Compute resize overlay box ratio if resize is configured
  const resizeBox = useMemo(() => {
    if (!dimensions || !effects?.resizeWidth || !effects?.resizeHeight) return null;
    const origRatio = dimensions.width / dimensions.height;
    const targetRatio = effects.resizeWidth / effects.resizeHeight;
    return {
      targetW: effects.resizeWidth,
      targetH: effects.resizeHeight,
      ratioDiff: Math.abs(origRatio - targetRatio) > 0.02,
    };
  }, [dimensions, effects?.resizeWidth, effects?.resizeHeight]);

  return (
    <div
      className="relative w-full h-full overflow-hidden select-none cursor-grab active:cursor-grabbing flex items-center justify-center"
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onWheel={onWheel}
      style={{
        backgroundImage:
          "conic-gradient(rgba(128,128,128,0.15) 90deg, transparent 90deg 180deg, rgba(128,128,128,0.15) 180deg 270deg, transparent 270deg)",
        backgroundSize: "20px 20px",
      }}
    >
      {/* Scaled and panned viewport container */}
      <div
        className="relative flex items-center justify-center transition-transform duration-75"
        style={{
          transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`,
          transformOrigin: "center center",
          width: fitMode === "100%" && dimensions ? `${dimensions.width}px` : "100%",
          height: fitMode === "100%" && dimensions ? `${dimensions.height}px` : "100%",
        }}
      >
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={objectUrl}
          alt={file.name}
          onLoad={onImageLoad}
          draggable={false}
          className="max-w-full max-h-full object-contain pointer-events-none drop-shadow-sm transition-all duration-150"
          style={{
            filter,
            transform,
          }}
        />

        {/* Target resize frame overlay */}
        {resizeBox && (
          <div
            className="absolute pointer-events-none border-2 border-dashed border-primary/70 bg-primary/10 rounded-sm flex items-end justify-end p-1.5"
            style={{
              width: "90%",
              height: "90%",
            }}
          >
            <span className="text-[10px] bg-background/80 text-foreground px-1 py-0.5 rounded font-mono shadow-xs">
              Target: {resizeBox.targetW} × {resizeBox.targetH}px
            </span>
          </div>
        )}
      </div>

      {/* Floating Info Pill at Bottom */}
      <div className="absolute bottom-3 left-3 right-3 flex items-center justify-between pointer-events-none text-[11px] gap-2">
        <div className="bg-background/90 backdrop-blur-md px-2.5 py-1 rounded-md border border-border/80 shadow-xs flex items-center gap-2 font-mono">
          <span>{file.name}</span>
          <span className="text-muted-foreground">•</span>
          {dimensions && (
            <>
              <span>
                {dimensions.width} × {dimensions.height}px
              </span>
              <span className="text-muted-foreground">•</span>
            </>
          )}
          <span>{formatBytes(file.size)}</span>
        </div>

        {estimatedSize !== null && (
          <div className="bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 backdrop-blur-md px-2.5 py-1 rounded-md shadow-xs font-mono font-medium">
            Est. ~{formatBytes(estimatedSize)}
          </div>
        )}
      </div>
    </div>
  );
}

// src/components/preview/PdfPreview.tsx
"use client";

import React, { useEffect, useRef, useState, useCallback } from "react";
import type { PDFDocumentProxy, RenderTask } from "pdfjs-dist";
import { getPdfjs } from "@/lib/pdf-editor/pdfjs";
import { formatBytes } from "@/lib/utils";
import type { PreviewEffects } from "./types";
import { AlertCircle, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";

interface PdfPreviewProps {
  file: File;
  effects?: PreviewEffects;
  zoom: number;
  pan: { x: number; y: number };
  fitMode: "fit" | "100%";
  currentPage: number;
  onPageCountChange: (total: number) => void;
  onPointerDown: (e: React.PointerEvent) => void;
  onPointerMove: (e: React.PointerEvent) => void;
  onPointerUp: (e: React.PointerEvent) => void;
  onWheel: (e: React.WheelEvent) => void;
}

export function PdfPreview({
  file,
  effects,
  zoom,
  pan,
  fitMode,
  currentPage,
  onPageCountChange,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onWheel,
}: PdfPreviewProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);

  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [pageDims, setPageDims] = useState<{ width: number; height: number } | null>(null);

  const pdfDocRef = useRef<PDFDocumentProxy | null>(null);
  const renderTaskRef = useRef<RenderTask | null>(null);
  const currentRequestIdRef = useRef<number>(0);

  // Load PDF document proxy once per file
  useEffect(() => {
    let active = true;
    setLoading(true);
    setError(null);

    async function loadDoc() {
      try {
        const pdfjs = await getPdfjs();
        const buffer = await file.arrayBuffer();
        if (!active) return;

        const doc = await pdfjs.getDocument({
          data: new Uint8Array(buffer),
          stopAtErrors: false,
        }).promise;

        if (!active) {
          doc.destroy();
          return;
        }

        pdfDocRef.current = doc;
        onPageCountChange(doc.numPages);
        setLoading(false);
      } catch (err: unknown) {
        if (!active) return;
        const msg = err instanceof Error ? err.message : "Failed to load PDF";
        setError(msg);
        setLoading(false);
      }
    }

    loadDoc();

    return () => {
      active = false;
      renderTaskRef.current?.cancel();
      if (pdfDocRef.current) {
        pdfDocRef.current.destroy();
        pdfDocRef.current = null;
      }
    };
  }, [file, onPageCountChange]);

  // Render current page onto canvas
  const renderPage = useCallback(async () => {
    const doc = pdfDocRef.current;
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!doc || !canvas || !container) return;

    const reqId = ++currentRequestIdRef.current;

    // Cancel existing render
    if (renderTaskRef.current) {
      renderTaskRef.current.cancel();
      renderTaskRef.current = null;
    }

    try {
      const pageNum = Math.max(1, Math.min(currentPage, doc.numPages));
      const page = await doc.getPage(pageNum);
      if (reqId !== currentRequestIdRef.current) return;

      const unscaledViewport = page.getViewport({ scale: 1 });
      setPageDims({
        width: Math.round(unscaledViewport.width),
        height: Math.round(unscaledViewport.height),
      });

      // Fit calculation
      const containerW = container.clientWidth || 600;
      const containerH = container.clientHeight || 500;
      const fitScale = Math.min(
        (containerW - 32) / unscaledViewport.width,
        (containerH - 32) / unscaledViewport.height,
      );

      const baseScale = fitMode === "100%" ? 1 : Math.max(0.2, fitScale);
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const renderScale = baseScale * dpr;

      const viewport = page.getViewport({ scale: renderScale });

      // Cap at 16 megapixels to prevent memory exhaustion
      const maxArea = 16_000_000;
      let finalW = Math.max(1, Math.floor(viewport.width));
      let finalH = Math.max(1, Math.floor(viewport.height));
      if (finalW * finalH > maxArea) {
        const factor = Math.sqrt(maxArea / (finalW * finalH));
        finalW = Math.floor(finalW * factor);
        finalH = Math.floor(finalH * factor);
      }

      canvas.width = finalW;
      canvas.height = finalH;
      canvas.style.width = `${Math.floor(finalW / dpr)}px`;
      canvas.style.height = `${Math.floor(finalH / dpr)}px`;

      const ctx = canvas.getContext("2d", { alpha: false });
      if (!ctx) return;

      const task = page.render({
        canvasContext: ctx,
        viewport,
      });
      renderTaskRef.current = task;

      await task.promise;
      if (reqId === currentRequestIdRef.current) {
        renderTaskRef.current = null;
      }
    } catch (err: unknown) {
      if ((err as { name?: string })?.name === "RenderingCancelledException") {
        return;
      }
      setError("Failed to render page");
    }
  }, [currentPage, fitMode]);

  useEffect(() => {
    if (!loading && pdfDocRef.current) {
      renderPage();
    }
  }, [loading, renderPage]);

  // Handle container resize
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const observer = new ResizeObserver(() => {
      renderPage();
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, [renderPage]);

  // CSS rotation from effects
  const rotationDeg = effects?.pdfRotation ?? effects?.rotateDeg ?? 0;

  if (error) {
    return (
      <div className="w-full h-full grid place-items-center p-6 text-center">
        <div className="space-y-3 max-w-sm">
          <AlertCircle className="w-8 h-8 text-destructive mx-auto" />
          <p className="text-sm font-medium">{error}</p>
          <Button variant="outline" size="sm" onClick={() => renderPage()}>
            Retry
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div
      ref={containerRef}
      className="relative w-full h-full overflow-hidden select-none cursor-grab active:cursor-grabbing flex items-center justify-center bg-zinc-900/40"
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onWheel={onWheel}
    >
      {loading && (
        <div className="absolute inset-0 grid place-items-center bg-card/60 z-20">
          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            <Loader2 className="w-4 h-4 animate-spin text-primary" />
            <span>Loading PDF...</span>
          </div>
        </div>
      )}

      {/* Canvas container with zoom, pan, and rotation */}
      <div
        className="relative transition-transform duration-75 flex items-center justify-center"
        style={{
          transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom}) rotate(${rotationDeg}deg)`,
          transformOrigin: "center center",
        }}
      >
        <canvas
          ref={canvasRef}
          className="shadow-md bg-white rounded-xs pointer-events-none"
        />

        {/* Live Watermark Overlay (Step 3 ready) */}
        {effects?.watermarkText && (
          <div className="absolute inset-0 pointer-events-none flex items-center justify-center overflow-hidden">
            <span
              className="text-muted-foreground/30 font-bold select-none text-center transform -rotate-45"
              style={{ fontSize: "calc(3rem + 2vw)" }}
            >
              {effects.watermarkText}
            </span>
          </div>
        )}
      </div>

      {/* Floating Info Pill at Bottom */}
      <div className="absolute bottom-3 left-3 right-3 flex items-center justify-between pointer-events-none text-[11px]">
        <div className="bg-background/90 backdrop-blur-md px-2.5 py-1 rounded-md border border-border/80 shadow-xs flex items-center gap-2 font-mono">
          <span>{file.name}</span>
          <span className="text-muted-foreground">•</span>
          {pageDims && (
            <>
              <span>
                {pageDims.width} × {pageDims.height} pt
              </span>
              <span className="text-muted-foreground">•</span>
            </>
          )}
          <span>{formatBytes(file.size)}</span>
        </div>
      </div>
    </div>
  );
}

