              <span className="text-muted-foreground">•</span>
            </>
          )}
          <span>{formatBytes(file.size)}</span>
        </div>
      </div>
    </div>
  );
}

// src/components/preview/ImagePreview.tsx
"use client";

import React, { useEffect, useState, useMemo, useRef } from "react";
import { formatBytes, cn } from "@/lib/utils";
import type { PreviewEffects } from "./types";
import { getEffectCss, estimateOutputSize } from "./preview-utils";

interface ImagePreviewProps {
  file: File;
  objectUrl: string;
  effects?: PreviewEffects;
  zoom: number;
  pan: { x: number; y: number };
  fitMode: "fit" | "100%";
  showOriginal: boolean;
  isDragging: boolean;
  onPointerDown: (e: React.PointerEvent) => void;
  onPointerMove: (e: React.PointerEvent) => void;
  onPointerUp: (e: React.PointerEvent) => void;
  onWheel: (e: React.WheelEvent) => void;
}

export function ImagePreview({
  file,
  objectUrl,
  effects,
  zoom,
  pan,
  fitMode,
  showOriginal,
  isDragging,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onWheel,
}: ImagePreviewProps) {
  const [dimensions, setDimensions] = useState<{ width: number; height: number } | null>(null);
  const [estimatedSize, setEstimatedSize] = useState<number | null>(null);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  // Measure natural dimensions on image load
  const onImageLoad = (e: React.SyntheticEvent<HTMLImageElement>) => {
    const img = e.currentTarget;
    setDimensions({ width: img.naturalWidth, height: img.naturalHeight });
  };

  // Debounced estimated output size calculation
  useEffect(() => {
    if (timerRef.current) clearTimeout(timerRef.current);

    timerRef.current = setTimeout(async () => {
      if (effects?.quality || effects?.targetFormat || effects?.resizeWidth) {
        const est = await estimateOutputSize(
          file,
          effects?.targetFormat,
          effects?.quality,
          effects?.resizeWidth,
          effects?.resizeHeight,
        );
        setEstimatedSize(est);
      } else {
        setEstimatedSize(null);
      }
    }, 300);

    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [file, effects]);

  const { filter, transform } = useMemo(() => {
    if (showOriginal) {
      return { filter: "none", transform: "none", hasEffects: false };
    }
    return getEffectCss(effects);
  }, [effects, showOriginal]);

  // Compute resize overlay box ratio if resize is configured
  const resizeBox = useMemo(() => {
    if (!dimensions || !effects?.resizeWidth || !effects?.resizeHeight) return null;
    const origRatio = dimensions.width / dimensions.height;
    const targetRatio = effects.resizeWidth / effects.resizeHeight;
    return {
      targetW: effects.resizeWidth,
      targetH: effects.resizeHeight,
      ratioDiff: Math.abs(origRatio - targetRatio) > 0.02,
    };
  }, [dimensions, effects]);

  return (
    <div
      className={cn(
        "relative w-full h-full overflow-hidden select-none flex items-center justify-center",
        isDragging ? "cursor-grabbing" : "cursor-grab",
      )}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onWheel={onWheel}
      style={{
        backgroundImage:
          "conic-gradient(rgba(128,128,128,0.15) 90deg, transparent 90deg 180deg, rgba(128,128,128,0.15) 180deg 270deg, transparent 270deg)",
        backgroundSize: "20px 20px",
      }}
    >
      {/* Scaled and panned viewport container */}
      <div
        className="relative flex items-center justify-center transition-transform duration-75"
        style={{
          transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`,
          transformOrigin: "center center",
          width: fitMode === "100%" && dimensions ? `${dimensions.width}px` : "100%",
          height: fitMode === "100%" && dimensions ? `${dimensions.height}px` : "100%",
        }}
      >
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={objectUrl}
          alt={file.name}
          onLoad={onImageLoad}
          draggable={false}
          className="max-w-full max-h-full object-contain pointer-events-none drop-shadow-sm transition-all duration-150"
          style={{
            filter,
            transform,
          }}
        />

        {/* Target resize frame overlay */}
        {resizeBox && (
          <div
            className="absolute pointer-events-none border-2 border-dashed border-primary/70 bg-primary/10 rounded-sm flex items-end justify-end p-1.5"
            style={{
              width: "90%",
              height: "90%",
            }}
          >
            <span className="text-[10px] bg-background/80 text-foreground px-1 py-0.5 rounded font-mono shadow-xs">
              Target: {resizeBox.targetW} × {resizeBox.targetH}px
            </span>
          </div>
        )}
      </div>

      {/* Floating Info Pill at Bottom */}
      <div className="absolute bottom-3 left-3 right-3 flex items-center justify-between pointer-events-none text-[11px] gap-2">
        <div className="bg-background/90 backdrop-blur-md px-2.5 py-1 rounded-md border border-border/80 shadow-xs flex items-center gap-2 font-mono">
          <span>{file.name}</span>
          <span className="text-muted-foreground">•</span>
          {dimensions && (
            <>
              <span>
                {dimensions.width} × {dimensions.height}px
              </span>
              <span className="text-muted-foreground">•</span>
            </>
          )}
          <span>{formatBytes(file.size)}</span>
        </div>

        {estimatedSize !== null && (
          <div className="bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 backdrop-blur-md px-2.5 py-1 rounded-md shadow-xs font-mono font-medium">
            Est. ~{formatBytes(estimatedSize)}
          </div>
        )}
      </div>
    </div>
  );
}

// src/components/preview/usePreview.ts
"use client";

import { useEffect, useRef, useState, useCallback } from "react";

export interface UsePreviewReturn {
  objectUrl: string | null;
  zoom: number;
  fitMode: "fit" | "100%";
  pan: { x: number; y: number };
  isDragging: boolean;
  showOriginal: boolean;
  setShowOriginal: (show: boolean) => void;
  setFitMode: (mode: "fit" | "100%") => void;
  zoomIn: () => void;
  zoomOut: () => void;
  resetZoom: () => void;
  onPointerDown: (e: React.PointerEvent) => void;
  onPointerMove: (e: React.PointerEvent) => void;
  onPointerUp: (e: React.PointerEvent) => void;
  onWheel: (e: React.WheelEvent) => void;
}

export function usePreview(file: File | null): UsePreviewReturn {
  const [objectUrl, setObjectUrl] = useState<string | null>(null);
  const [zoom, setZoom] = useState<number>(1);
  const [fitMode, setFitMode] = useState<"fit" | "100%">("fit");
  const [pan, setPan] = useState<{ x: number; y: number }>({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState<boolean>(false);
  const [showOriginal, setShowOriginal] = useState<boolean>(false);

  // Sync / reset during render when file changes (React 19 pattern)
  const [prevFile, setPrevFile] = useState<File | null>(file);
  if (file !== prevFile) {
    setPrevFile(file);
    setZoom(1);
    setFitMode("fit");
    setPan({ x: 0, y: 0 });
    setShowOriginal(false);
    if (!file) {
      setObjectUrl(null);
    }
  }

  const dragStartRef = useRef<{ x: number; y: number } | null>(null);
  const rafRef = useRef<number | null>(null);

  // Object URL lifecycle: create on file change, always revoke on change & unmount
  useEffect(() => {
    if (!file) return;

    const url = URL.createObjectURL(file);
    let active = true;

    queueMicrotask(() => {
      if (active) setObjectUrl(url);
    });

    return () => {
      active = false;
      URL.revokeObjectURL(url);
    };
  }, [file]);

  const zoomIn = useCallback(() => {
    setFitMode("100%");
    setZoom((prev) => Math.min(4, +(prev + 0.25).toFixed(2)));
  }, []);

  const zoomOut = useCallback(() => {
    setFitMode("100%");
    setZoom((prev) => Math.max(0.25, +(prev - 0.25).toFixed(2)));
  }, []);

  const resetZoom = useCallback(() => {
    setFitMode("fit");
    setZoom(1);
    setPan({ x: 0, y: 0 });
  }, []);

  const onPointerDown = useCallback((e: React.PointerEvent) => {
    if (e.button !== 0) return; // Left click only
    dragStartRef.current = { x: e.clientX, y: e.clientY };
    setIsDragging(true);
    (e.currentTarget as HTMLElement).setPointerCapture?.(e.pointerId);
  }, []);

  const onPointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!dragStartRef.current || !isDragging) return;
      const dx = e.clientX - dragStartRef.current.x;
      const dy = e.clientY - dragStartRef.current.y;
      dragStartRef.current = { x: e.clientX, y: e.clientY };

      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      rafRef.current = requestAnimationFrame(() => {
        setPan((prev) => ({ x: prev.x + dx, y: prev.y + dy }));
      });
    },
    [isDragging],
  );

  const onPointerUp = useCallback((e: React.PointerEvent) => {
    dragStartRef.current = null;
    setIsDragging(false);
    try {
      (e.currentTarget as HTMLElement).releasePointerCapture?.(e.pointerId);
    } catch {
      // Ignored
    }
  }, []);

  const onWheel = useCallback((e: React.WheelEvent) => {
    if (e.ctrlKey || e.metaKey) {
      e.preventDefault();
      const delta = e.deltaY < 0 ? 0.15 : -0.15;
      setFitMode("100%");
      setZoom((prev) => Math.min(4, Math.max(0.25, +(prev + delta).toFixed(2))));
    }
  }, []);

  return {
    objectUrl,
    zoom,
    fitMode,
    pan,
    isDragging,
    showOriginal,
    setShowOriginal,
    setFitMode,
    zoomIn,
    zoomOut,
    resetZoom,
    onPointerDown,
    onPointerMove,
    onPointerUp,
    onWheel,
  };
}

// src/components/preview/PreviewPanel.tsx
"use client";

import React, { useState, useMemo } from "react";
import { FileSearch, X } from "lucide-react";
import { cn } from "@/lib/utils";
import type { PreviewPanelProps } from "./types";
import { getFileCategory } from "./preview-utils";
import { usePreview } from "./usePreview";
import { PreviewToolbar } from "./PreviewToolbar";
import { ImagePreview } from "./ImagePreview";
import { PdfPreview } from "./PdfPreview";
import { FileCardPreview } from "./FileCardPreview";

export function PreviewPanel({
  files,
  effects,
  activeFileIndex = 0,
  onSelectFile,
  onRemoveFile,
  className,
}: PreviewPanelProps) {
  const [internalActiveIndex, setInternalActiveIndex] = useState(0);
  const [totalPages, setTotalPages] = useState<number>(1);
  const [currentPage, setCurrentPage] = useState<number>(1);

  const selectedIndex = onSelectFile ? activeFileIndex : internalActiveIndex;
  const activeFile = files[selectedIndex] || files[0] || null;

  const handleSelect = (idx: number) => {
    if (onSelectFile) onSelectFile(idx);
    else setInternalActiveIndex(idx);
    setCurrentPage(1);
  };

  const {
    objectUrl,
    zoom,
    fitMode,
    pan,
    isDragging,
    showOriginal,
    setShowOriginal,
    setFitMode,
    zoomIn,
    zoomOut,
    resetZoom,
    onPointerDown,
    onPointerMove,
    onPointerUp,
    onWheel,
  } = usePreview(activeFile);

  const category = useMemo(() => {
    return activeFile ? getFileCategory(activeFile) : "other";
  }, [activeFile]);

  // If no files are added yet
  if (!activeFile) {
    return (
      <div
        className={cn(
          "w-full h-[45vh] lg:h-[min(70vh,720px)] rounded-2xl border-2 border-dashed border-border/80 bg-muted/20 flex flex-col items-center justify-center p-6 text-center text-muted-foreground space-y-3",
          className,
        )}
      >
        <div className="p-4 rounded-full bg-muted/60 border border-border/50 text-muted-foreground/70">
          <FileSearch className="w-8 h-8" />
        </div>
        <div className="space-y-1">
          <p className="font-medium text-sm text-foreground">Live Preview</p>
          <p className="text-xs">Add a file to see a preview in real time.</p>
        </div>
      </div>
    );
  }

  const hasEffects = Boolean(
    effects &&
      (effects.brightness !== 100 ||
        effects.contrast !== 100 ||
        effects.saturation !== 100 ||
        (effects.grayscale ?? 0) > 0 ||
        (effects.rotateDeg ?? 0) !== 0 ||
        effects.flipH ||
        effects.flipV ||
        effects.resizeWidth ||
        effects.resizeHeight),
  );

  return (
    <div
      className={cn(
        "w-full flex flex-col rounded-2xl border border-border bg-card shadow-xs overflow-hidden",
        "lg:sticky lg:top-20 h-[45vh] lg:h-[min(70vh,720px)]",
        className,
      )}
    >
      {/* Top Toolbar */}
      <PreviewToolbar
        zoom={zoom}
        fitMode={fitMode}
        onZoomIn={zoomIn}
        onZoomOut={zoomOut}
        onResetZoom={resetZoom}
        onToggleFit={() => setFitMode(fitMode === "fit" ? "100%" : "fit")}
        hasEffects={category === "image" && hasEffects}
        showOriginal={showOriginal}
        onToggleOriginal={setShowOriginal}
        isApproximate={hasEffects}
        currentPage={currentPage}
        totalPages={category === "pdf" ? totalPages : undefined}
        onPrevPage={() => setCurrentPage((p) => Math.max(1, p - 1))}
        onNextPage={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
      />

      {/* Main Preview Content */}
      <div className="relative flex-1 w-full overflow-hidden min-h-0 bg-background/50">
        {category === "image" && objectUrl && (
          <ImagePreview
            file={activeFile}
            objectUrl={objectUrl}
            effects={effects}
            zoom={zoom}
            pan={pan}
            fitMode={fitMode}
            showOriginal={showOriginal}
            isDragging={isDragging}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            onWheel={onWheel}
          />
        )}

        {category === "pdf" && (
          <PdfPreview
            file={activeFile}
            effects={effects}
            zoom={zoom}
            pan={pan}
            fitMode={fitMode}
            currentPage={currentPage}
            onPageCountChange={setTotalPages}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            onWheel={onWheel}
          />
        )}

        {category !== "image" && category !== "pdf" && (
          <FileCardPreview
            file={activeFile}
            category={category}
            objectUrl={objectUrl}
          />
        )}
      </div>

      {/* Multiple Files Thumbnail Strip */}
      {files.length > 1 && (
        <div className="h-18 px-3 py-2 bg-muted/30 border-t border-border flex items-center gap-2 overflow-x-auto shrink-0 select-none">
          <span className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider pl-1 pr-1 shrink-0">
            {files.length} Files
          </span>
          {files.map((f, i) => {
            const isSelected = i === selectedIndex;
            return (
              <div
                key={`${f.name}-${i}`}
                onClick={() => handleSelect(i)}
                className={cn(
                  "relative group h-13 w-16 shrink-0 rounded-lg border transition-all cursor-pointer overflow-hidden p-1 flex flex-col justify-between text-left",
                  isSelected
                    ? "border-primary bg-primary/10 shadow-xs ring-1 ring-primary"
                    : "border-border/70 bg-card hover:border-primary/50",
                )}
              >
                <div className="flex items-center justify-between gap-1">
                  <span className="text-[9px] font-mono text-muted-foreground uppercase truncate">
                    {f.name.split(".").pop()}
                  </span>
                  {onRemoveFile && (
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        onRemoveFile(i);
                      }}
                      className="opacity-0 group-hover:opacity-100 hover:text-destructive transition-opacity"
                    >
                      <X className="w-3 h-3" />
                    </button>
                  )}
                </div>
                <p className="text-[10px] font-medium truncate leading-tight">
                  {f.name}
                </p>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

