      watermarkColor: tool.id === "pdf-watermark" ? watermarkColor : undefined,
      pageNumbers:
        tool.id === "pdf-page-numbers"
          ? {
              position: numberPosition,
              start: pageNumStart,
              format: pageNumFormat,
            }
          : undefined,
    };
  }, [
    tool.id,
    rotateAngle,
    watermarkText,
    watermarkOpacity,
    watermarkPosition,
