// src/lib/images-to-pdf-layout.ts
// Pure layout mathematics for Images to PDF.
// Used by BOTH the screen preview and pdf-lib export so preview == PDF.

export type PageSizeId = "fit" | "a4" | "letter" | "legal" | "a3" | "a5";
export type OrientationId = "auto" | "portrait" | "landscape";
export type MarginId = "none" | "small" | "medium" | "large";
export type FitModeId = "fit" | "fill" | "stretch" | "original";

export interface LayoutOptions {
  pageSize: PageSizeId;
  orientation: OrientationId;
  margin: MarginId;
  fit: FitModeId;
}

export interface LayoutResult {
  pageWidth: number;
  pageHeight: number;
  x: number;
  y: number;
  width: number;
  height: number;
  marginPt: number;
  effectiveImgWidth: number;
  effectiveImgHeight: number;
}

// Standard paper dimensions in points (72 points = 1 inch)
// Represented in portrait [width, height]
export const PAGE_SIZES: Record<Exclude<PageSizeId, "fit">, [number, number]> = {
  a4: [595.28, 841.89],
  letter: [612, 792],
  legal: [612, 1008],
  a3: [841.89, 1190.55],
  a5: [419.53, 595.28],
};

export const MARGIN_PTS: Record<MarginId, number> = {
  none: 0,
  small: 18, // 0.25 in
  medium: 36, // 0.5 in
  large: 54, // 0.75 in
};

/**
 * Normalizes rotation angle to 0, 90, 180, 270 degrees.
 */
export function normalizeRotation(deg: number): number {
  const mod = ((deg % 360) + 360) % 360;
  if (mod >= 45 && mod < 135) return 90;
  if (mod >= 135 && mod < 225) return 180;
  if (mod >= 225 && mod < 315) return 270;
  return 0;
}

/**
 * Calculates page dimensions and image placement rectangle.
 */
export function calculatePageLayout(
  imgWidth: number,
  imgHeight: number,
  rotation: number,
  options: LayoutOptions,
): LayoutResult {
  const normRot = normalizeRotation(rotation);
  const isRotated90or270 = normRot === 90 || normRot === 270;

  // Effective dimensions after rotation
  const effectiveImgWidth = isRotated90or270 ? imgHeight : imgWidth;
  const effectiveImgHeight = isRotated90or270 ? imgWidth : imgHeight;

  const marginPt = options.pageSize === "fit" ? 0 : (MARGIN_PTS[options.margin] ?? 0);

  let pageWidth: number;
  let pageHeight: number;

  if (options.pageSize === "fit") {
    pageWidth = Math.max(1, effectiveImgWidth);
    pageHeight = Math.max(1, effectiveImgHeight);
  } else {
    const baseDims = PAGE_SIZES[options.pageSize] || PAGE_SIZES.a4;
    const shortSide = Math.min(baseDims[0], baseDims[1]);
    const longSide = Math.max(baseDims[0], baseDims[1]);

    let isLandscape = false;
    if (options.orientation === "landscape") {
      isLandscape = true;
    } else if (options.orientation === "portrait") {
      isLandscape = false;
    } else {
      // "auto": match image's aspect ratio
      isLandscape = effectiveImgWidth > effectiveImgHeight;
    }

    pageWidth = isLandscape ? longSide : shortSide;
    pageHeight = isLandscape ? shortSide : longSide;
  }

  // Printable area inside margins
  const printableW = Math.max(1, pageWidth - 2 * marginPt);
  const printableH = Math.max(1, pageHeight - 2 * marginPt);

  let drawW: number;
  let drawH: number;

  if (options.fit === "stretch") {
    drawW = printableW;
    drawH = printableH;
  } else if (options.fit === "fill") {
    // Cover: scale to fill, preserving ratio
    const scale = Math.max(
      printableW / effectiveImgWidth,
      printableH / effectiveImgHeight,
    );
    drawW = effectiveImgWidth * scale;
    drawH = effectiveImgHeight * scale;
  } else if (options.fit === "original") {
    // 1 pt per pixel, but scale down if it exceeds printable bounds
    const scale = Math.min(
      1,
      printableW / effectiveImgWidth,
      printableH / effectiveImgHeight,
    );
    drawW = effectiveImgWidth * scale;
    drawH = effectiveImgHeight * scale;
  } else {
    // "fit" (contain): default
    const scale = Math.min(
      printableW / effectiveImgWidth,
      printableH / effectiveImgHeight,
    );
    drawW = effectiveImgWidth * scale;
    drawH = effectiveImgHeight * scale;
  }

  // Center within printable area
  const x = marginPt + (printableW - drawW) / 2;
  const y = marginPt + (printableH - drawH) / 2;

  return {
    pageWidth,
    pageHeight,
    x,
    y,
    width: drawW,
    height: drawH,
    marginPt,
    effectiveImgWidth,
    effectiveImgHeight,
  };
}

import test from "node:test";
import assert from "node:assert/strict";
import {
  calculatePageLayout,
  normalizeRotation,
  PAGE_SIZES,
  MARGIN_PTS,
} from "../src/lib/images-to-pdf-layout.ts";

test("images-to-pdf layout math suite", async (t) => {
  await t.test("normalizeRotation correctly normalizes angles", () => {
    assert.equal(normalizeRotation(0), 0);
    assert.equal(normalizeRotation(90), 90);
    assert.equal(normalizeRotation(180), 180);
    assert.equal(normalizeRotation(270), 270);
    assert.equal(normalizeRotation(360), 0);
    assert.equal(normalizeRotation(-90), 270);
    assert.equal(normalizeRotation(450), 90);
  });

  await t.test("fit page size sets page dimensions to image dimensions", () => {
    const layout = calculatePageLayout(800, 600, 0, {
      pageSize: "fit",
      orientation: "auto",
      margin: "none",
      fit: "fit",
    });
    assert.equal(layout.pageWidth, 800);
    assert.equal(layout.pageHeight, 600);
    assert.equal(layout.x, 0);
    assert.equal(layout.y, 0);
    assert.equal(layout.width, 800);
    assert.equal(layout.height, 600);
  });

  await t.test("fit page size swaps dimensions when rotated 90 deg", () => {
    const layout = calculatePageLayout(800, 600, 90, {
      pageSize: "fit",
      orientation: "auto",
      margin: "none",
      fit: "fit",
    });
    assert.equal(layout.pageWidth, 600);
    assert.equal(layout.pageHeight, 800);
    assert.equal(layout.effectiveImgWidth, 600);
    assert.equal(layout.effectiveImgHeight, 800);
  });

  await t.test("orientation auto selects portrait for tall images", () => {
    const layout = calculatePageLayout(500, 1000, 0, {
      pageSize: "a4",
      orientation: "auto",
      margin: "none",
      fit: "fit",
    });
    assert.equal(layout.pageWidth, PAGE_SIZES.a4[0]);
    assert.equal(layout.pageHeight, PAGE_SIZES.a4[1]);
  });

  await t.test("orientation auto selects landscape for wide images", () => {
    const layout = calculatePageLayout(1000, 500, 0, {
      pageSize: "a4",
      orientation: "auto",
      margin: "none",
      fit: "fit",
    });
    assert.equal(layout.pageWidth, PAGE_SIZES.a4[1]);
    assert.equal(layout.pageHeight, PAGE_SIZES.a4[0]);
  });

  await t.test("margins reduce printable area and center image", () => {
    const marginKey = "medium";
    const marginPt = MARGIN_PTS[marginKey];
    const layout = calculatePageLayout(400, 400, 0, {
      pageSize: "letter",
      orientation: "portrait",
      margin: marginKey,
      fit: "fit",
    });
    assert.equal(layout.marginPt, marginPt);
    const printableW = PAGE_SIZES.letter[0] - 2 * marginPt;
    const printableH = PAGE_SIZES.letter[1] - 2 * marginPt;
    // Since 400x400 is square, it will scale to printableW (the shorter side)
    assert.ok(Math.abs(layout.width - printableW) < 0.01);
    assert.ok(Math.abs(layout.height - printableW) < 0.01);
    assert.ok(Math.abs(layout.x - marginPt) < 0.01);
    assert.ok(Math.abs(layout.y - (marginPt + (printableH - layout.height) / 2)) < 0.01);
  });

  await t.test("fit modes: stretch, fill, original", () => {
    const stretch = calculatePageLayout(200, 400, 0, {
      pageSize: "a4",
      orientation: "portrait",
      margin: "none",
      fit: "stretch",
    });
    assert.equal(stretch.width, PAGE_SIZES.a4[0]);
    assert.equal(stretch.height, PAGE_SIZES.a4[1]);

    const fill = calculatePageLayout(200, 400, 0, {
      pageSize: "a4",
      orientation: "portrait",
      margin: "none",
      fit: "fill",
    });
    // Fill should cover both dimensions
    assert.ok(fill.width >= PAGE_SIZES.a4[0]);
    assert.ok(fill.height >= PAGE_SIZES.a4[1]);

    const original = calculatePageLayout(100, 150, 0, {
      pageSize: "a4",
      orientation: "portrait",
      margin: "none",
      fit: "original",
    });
    assert.equal(original.width, 100);
    assert.equal(original.height, 150);
  });
});

