11: function formatPageLabel(page: number, format?: string): string {
12:   switch (format) {
13:     case "roman":
14:       return toRoman(page);
15:     case "alpha":
16:       return String.fromCharCode(64 + ((page - 1) % 26) + 1);
17:     case "dash":
18:       return `- ${page} -`;
19:     case "page-n":
20:       return `Page ${page}`;
21:     case "numbers":
22:     default:
23:       return `${page}`;
24:   }
25: }
26: 
27: function toRoman(num: number): string {
28:   const lookup: [string, number][] = [
29:     ["m", 1000],
30:     ["cm", 900],
31:     ["d", 500],
32:     ["cd", 400],
33:     ["c", 100],
34:     ["xc", 90],
35:     ["l", 50],
36:     ["xl", 40],
37:     ["x", 10],
38:     ["ix", 9],
39:     ["v", 5],
40:     ["iv", 4],
41:     ["i", 1],
42:   ];
43:   let res = "";
44:   let n = num;
45:   for (const [letter, value] of lookup) {
46:     while (n >= value) {
47:       res += letter;
48:       n -= value;
49:     }
50:   }
51:   return res || "i";
52: }
