21: /** Cheap hash so re-extraction yields stable ids. */
22: function hashString(input: string): string {
23:   let h = 5381;
24:   for (let i = 0; i < input.length; i++) {
25:     h = ((h << 5) + h) ^ input.charCodeAt(i);
26:   }
27:   return (h >>> 0).toString(36);
