47:  * detecting bold and italic style variants accurately. Never emits raw font identifiers.
48:  */
49: export function mapPdfFontToWeb(
50:   rawName: string,
51:   styleFontFamily?: string,
52: ): {
53:   fontFamily: FontFamilyId;
54:   bold: boolean;
55:   italic: boolean;
56: } {
57:   // Strip 6-uppercase-letter PDF subset prefix like 'BCDEEE+' or 'XAAAAA+'
58:   const cleanName = rawName.replace(/^[A-Z]{6}\+/, "");
59:   const combined = `${cleanName} ${styleFontFamily || ""}`.toLowerCase();
60: 
61:   const bold = /bold|black|heavy|semibold|700|800|900/i.test(combined);
62:   const italic = /italic|oblique/i.test(combined);
63: 
64:   let fontFamily: FontFamilyId = "Arial";
65:   if (/noto\s*sans|noto/i.test(combined)) {
66:     fontFamily = "Noto Sans";
67:   } else if (/times|times\s*new\s*roman|timesnewroman/i.test(combined)) {
68:     fontFamily = "Times New Roman";
69:   } else if (/cambria/i.test(combined)) {
70:     fontFamily = "Cambria";
71:   } else if (/garamond/i.test(combined)) {
72:     fontFamily = "Garamond";
73:   } else if (/georgia/i.test(combined)) {
74:     fontFamily = "Georgia";
75:   } else if (/courier|mono|consolas/i.test(combined)) {
76:     fontFamily = "Courier New";
77:   } else if (/helvetica/i.test(combined)) {
78:     fontFamily = "Helvetica";
79:   } else if (/serif/i.test(combined)) {
80:     fontFamily = "Times New Roman";
81:   } else {
82:     fontFamily = "Arial";
83:   }
