88: /**
89:  * Extract all runs for a page. Skips whitespace-only items and items whose
90:  * rect has zero area (some PDFs emit those for spacing hints).
91:  */
92: export async function extractTextRuns(
93:   page: PDFPageProxy,
94:   pageInfo: PageInfo,
95:   options: ExtractOptions = {},
96: ): Promise<TextRunObject[]> {
97:   const content = await page.getTextContent();
98:   const items = (content.items ?? []) as unknown as PdfjsTextItem[];
99: 
100:   // Explicitly type the styles record instead of using `any`
101:   const styles = (content.styles || {}) as Record<
102:     string,
103:     { fontFamily?: string }
104:   >;
105: 
106:   const out: TextRunObject[] = [];
107:   const seen = new Set<string>();
108: 
109:   for (let i = 0; i < items.length; i++) {
110:     const item = items[i];
111:     const text = typeof item.str === "string" ? item.str : "";
112:     if (!text.trim()) continue;
113: 
114:     const rect = pdfjsTextItemToPdfRect({
115:       transform: item.transform,
116:       width: item.width,
117:       height: item.height,
118:     });
119:     if (rect.w <= 0.1 || rect.h <= 0.1) continue;
120: 
121:     // Use pageUid to prevent collisions on duplicated pages
122:     const id = makeRunId(pageUid(pageInfo), i, text);
123:     if (seen.has(id)) continue;
124:     seen.add(id);
125: 
126:     // Extract exact font details from pdfjs styles mapped to clean web fonts
127:     const style = styles[item.fontName || ""] || {};
128:     const fontInfo = mapPdfFontToWeb(item.fontName || "", style.fontFamily);
129: 
130:     // Font size from the linear part of the transform matrix
131:     const a = item.transform[0] ?? 1;
132:     const b = item.transform[1] ?? 0;
133:     const c = item.transform[2] ?? 0;
134:     const d = item.transform[3] ?? 1;
135:     const fontSize = Math.max(4, Math.hypot(c, d) || Math.hypot(a, b) || 10);
136: 
137:     const bg = options.sampleBackground
138:       ? options.sampleBackground(rect)
139:       : (options.defaultBackground ?? "#ffffff");
140: 
141:     const run: TextRunObject = {
142:       id,
143:       kind: "text-run",
144:       page: pageInfo.index,
145:       rect,
146:       rotation: 0,
147:       z: out.length,
148:       locked: false,
149:       opacity: 1,
150:       dirty: false,
151:       text,
152:       originalText: text,
153:       sourceFontName: item.fontName || style.fontFamily || "unknown",
154:       fontFamily: fontInfo.fontFamily,
155:       substituted: false,
156:       fontSize,
157:       bold: fontInfo.bold,
158:       italic: fontInfo.italic,
159:       underline: false,
160:       color: "#000000",
161:       align: "left",
162:       lineHeight: 1.2,
163:       letterSpacing: 0,
164:       backgroundColor: normalizeHexColor(bg),
165:     };
166:     out.push(run);
167:   }
168: 
169:   // Sort for stable visual order: top → bottom, then left → right.
170:   out.sort((p, q) => {
171:     if (Math.abs(q.rect.y - p.rect.y) > 1) return q.rect.y - p.rect.y;
172:     return p.rect.x - q.rect.x;
173:   });
174: 
175:   // Reassign z after sorting so the array order matches the visual order.
176:   return out.map((run, idx) => ({ ...run, z: idx }));
177: }
178: 
179: /**
180:  * Merge freshly-extracted runs with any that already exist in the store.
181:  * Existing runs whose ids match a newly-extracted run keep their edited
182:  * state (`dirty`, `text`, style); new runs are added. Runs that no longer
183:  * appear in the PDF (user edited them away) are kept if `dirty` so the
184:  * user can still export them, otherwise dropped.
185:  */
186: export function reconcileTextRuns(
187:   existing: TextRunObject[],
188:   fresh: TextRunObject[],
189: ): TextRunObject[] {
190:   const byId = new Map(existing.map((r) => [r.id, r]));
191:   const merged: TextRunObject[] = [];
192:   const used = new Set<string>();
193: 
194:   for (const run of fresh) {
195:     const prior = byId.get(run.id);
196:     if (prior) {
197:       merged.push(prior);
198:       used.add(prior.id);
199:     } else {
200:       merged.push(run);
201:     }
202:   }
203: 
204:   for (const run of existing) {
205:     if (!used.has(run.id) && run.dirty) merged.push(run);
206:   }
207: 
208:   return merged;
209: }

