1: // src/lib/pdf-editor/background-sample.ts
2: // Sample the background colour of a rect on a rendered page canvas.
3: // Used to (a) paint an opaque cover behind redrawn text on export, and
4: // (b) colour-match the "editing" textarea inside the overlay.
5: //
6: // Robustness: we sample a sparse grid (not every pixel) for speed, discard
7: // near-transparent pixels (canvases may be painted on transparent bg), and
8: // use the median channel value per R/G/B so one noisy text glyph does not
9: // distort the result.
10: 
11: import type { PageInfo, RectPt } from "./types";
12: import { pdfRectToCss, normalizeHexColor } from "./coords";
13: 
14: const SAMPLE_GRID = 12; // 12×12 = 144 samples per rect
15: 
16: interface Rgba {
17: r: number;
18: g: number;
19: b: number;
20: a: number;
21: }
22: 
23: function clamp255(v: number): number {
24: return Math.max(0, Math.min(255, Math.round(v)));
25: }
26: 
27: function toHex(r: number, g: number, b: number): string {
28: const h = (n: number) => clamp255(n).toString(16).padStart(2, "0");
29: return `#${h(r)}${h(g)}${h(b)}`.toLowerCase();
30: }
31: 
32: function median(values: number[]): number {
33: if (values.length === 0) return 0;
34: const sorted = values.slice().sort((a, b) => a - b);
35: const mid = sorted.length >> 1;
36: return sorted.length % 2 === 0
37:     ? Math.round((sorted[mid - 1] + sorted[mid]) / 2)
38:     : sorted[mid];
39: }
40: 
41: /**
42:  * Sample a rect (in PDF points) from `sourceCanvas` (a rendered page at
43:  * `zoom`). Returns `#rrggbb`. Falls back to `#ffffff` for empty reads.
44:  */
45: export function sampleMedianBackground(
46: sourceCanvas: HTMLCanvasElement,
47: rect: RectPt,
48: page: PageInfo,
49: zoom: number,
50: ): string {
51: if (!sourceCanvas || sourceCanvas.width === 0) return "#ffffff";
52: 
53: const css = pdfRectToCss(rect, page, zoom);
54: const ctx = sourceCanvas.getContext("2d", { willReadFrequently: true });
55: if (!ctx) return "#ffffff";
56: 
57: // Expand the sample a few px outward so we catch the "paper" tone around
58: // antialiased glyph edges. Guard against canvas boundaries.
59: const pad = 2;
60: const x0 = Math.max(0, Math.floor(css.left - pad));
61: const y0 = Math.max(0, Math.floor(css.top - pad));
62: const x1 = Math.min(
63:     sourceCanvas.width - 1,
64:     Math.ceil(css.left + css.width + pad),
65: );
66: const y1 = Math.min(
67:     sourceCanvas.height - 1,
68:     Math.ceil(css.top + css.height + pad),
69: );
70: if (x1 <= x0 || y1 <= y0) return "#ffffff";
71: 
72: const w = x1 - x0;
73: const h = y1 - y0;
74: const stepX = Math.max(1, Math.floor(w / SAMPLE_GRID));
75: const stepY = Math.max(1, Math.floor(h / SAMPLE_GRID));
76: 
77: let imageData: ImageData;
78: try {
79:     imageData = ctx.getImageData(x0, y0, w, h);
80: } catch {
81:     // Tainted canvas — the caller painted cross-origin content.
82:     return "#ffffff";
83: }
84: 
85: const rs: number[] = [];
86: const gs: number[] = [];
87: const bs: number[] = [];
88: 
89: for (let sy = 0; sy < h; sy += stepY) {
90:     for (let sx = 0; sx < w; sx += stepX) {
91:     const idx = (sy * w + sx) * 4;
92:     const r = imageData.data[idx];
93:     const g = imageData.data[idx + 1];
94:     const b = imageData.data[idx + 2];
95:     const a = imageData.data[idx + 3];
96:     if (a < 8) continue; // skip near-transparent
97:     rs.push(r);
98:     gs.push(g);
99:     bs.push(b);
100:     }
101: }
102: 
103: if (rs.length === 0) return "#ffffff";
104: 
105: return toHex(median(rs), median(gs), median(bs));
106: }
107: 
108: /**
109:  * Sample the single pixel under a CSS point. Useful for the eyedropper.
110:  */
111: export function samplePoint(
112: sourceCanvas: HTMLCanvasElement,
113: cssX: number,
114: cssY: number,
115: ): string {
116: const ctx = sourceCanvas.getContext("2d", { willReadFrequently: true });
117: if (!ctx) return "#ffffff";
118: const x = Math.max(0, Math.min(sourceCanvas.width - 1, Math.floor(cssX)));
119: const y = Math.max(0, Math.min(sourceCanvas.height - 1, Math.floor(cssY)));
120: const d = ctx.getImageData(x, y, 1, 1).data;
121: if (d[3] < 8) return "#ffffff";
122: return toHex(d[0], d[1], d[2]);
123: }
124: 
125: /**
126:  * Helper for text-run extraction: given a text run's PDF rect, return the
127:  * dominant background. Exposed as a callback factory so `extractTextRuns`
128:  * can be called without knowing about canvases.
129:  */
130: export function makeBackgroundSampler(
131: sourceCanvas: HTMLCanvasElement,
132: page: PageInfo,
133: zoom: number,
134: ): (rect: RectPt) => string {
135: return (rect: RectPt) =>
136:     sampleMedianBackground(sourceCanvas, rect, page, zoom);
137: }
138: 
139: /** Re-export for convenience. */
140: export { normalizeHexColor };

