  } else if (/verdana/i.test(combined)) {
    fontFamily = "Verdana";
  } else if (/calibri/i.test(combined)) {
    fontFamily = "Calibri";
  } else if (/noto\s*sans|noto/i.test(combined)) {
    fontFamily = "Noto Sans";
  } else if (/palatino|palatlinotype/i.test(combined)) {
    fontFamily = "Palatino";
  } else if (/garamond/i.test(combined)) {
    fontFamily = "Garamond";
  } else if (/cambria/i.test(combined)) {
    fontFamily = "Cambria";
  } else if (/georgia/i.test(combined)) {
    fontFamily = "Georgia";
  } else if (/merriweather/i.test(combined)) {
    fontFamily = "Merriweather";
  } else if (/times|timesnewroman|times\s*new\s*roman/i.test(combined)) {
    fontFamily = "Times New Roman";
  } else if (/consolas/i.test(combined)) {
    fontFamily = "Consolas";
  } else if (/courier/i.test(combined)) {
    fontFamily = "Courier New";
  } else if (/helvetica/i.test(combined)) {
    fontFamily = "Helvetica";
  } else if (/arial/i.test(combined)) {
    fontFamily = "Arial";
  } else {
    // Unknown font — use serif/mono/sans flags from pdfjs FontFlags
    // Bit 2 (0x2) = FixedPitch, Bit 1 (0x1) = Serif
    const flags = fontFlags ?? 0;
    if ((flags & 0x2) !== 0) {
      fontFamily = "Courier New"; // monospace
    } else if ((flags & 0x1) !== 0) {
      fontFamily = "Times New Roman"; // serif
    } else {
      fontFamily = "Arial"; // sans default
    }
  }

  return { fontFamily, bold, italic };
}

