// src/lib/pdf-editor/text-runs.ts
// Extract text runs from a pdfjs page. Each run becomes a TextRunObject that
// the editor can anchor an overlay textarea to. Untouched runs are marked
// `dirty: false` and are excluded from export — only dirty runs get the
// cover + redraw treatment.

import type { PDFPageProxy } from "pdfjs-dist";
import type { FontFamilyId, PageInfo, RectPt, TextRunObject } from "./types";
import { normalizeHexColor, pageUid, pdfjsTextItemToPdfRect } from "./coords";
import {
  extractColoursByOperatorList,
  resolveTextColour,
} from "./text-color";

/** Subset of `TextItem` we actually consume (pdfjs v6). */
interface PdfjsTextItem {
  str: string;
  transform: number[]; // [a b c d e f]
  width: number;
  height: number;
  fontName?: string;
  hasEOL?: boolean;
}

/** Cheap hash so re-extraction yields stable ids. */
function hashString(input: string): string {
  let h = 5381;
  for (let i = 0; i < input.length; i++) {
    h = ((h << 5) + h) ^ input.charCodeAt(i);
  }
  return (h >>> 0).toString(36);
}

/**
 * Deterministic id for a run. Two extractions of the same page produce
 * identical ids so the store can merge them without duplicates.
 */
function makeRunId(pageKey: string, itemIndex: number, text: string): string {
  return `run-${pageKey}-${itemIndex}-${hashString(text)}`;
}

interface ExtractOptions {
  /** Called once per run to sample the background colour under it. */
  sampleBackground?: (rect: RectPt) => string;
  /** Fallback colour if no sampler is provided. */
  defaultBackground?: string;
  /**
   * The pdfjs module object. When provided, operator-list colour extraction
   * is attempted before canvas fallback. Pass the result of `getPdfjs()`.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  pdfjsModule?: any;
}

/**
 * Map raw PDF font names (and optional pdfjs style fontFamily) to a clean web FontFamilyId,
 * detecting bold and italic style variants accurately. Never emits raw font identifiers.
 */
export function mapPdfFontToWeb(
  rawName: string,
  styleFontFamily?: string,
  /** Optional pdfjs font flags bitmask (FontFlags enum). */
  fontFlags?: number,
): {
  fontFamily: FontFamilyId;
  bold: boolean;
  italic: boolean;
} {
  // Strip 6-uppercase-letter PDF subset prefix like 'BCDEEE+' or 'XAAAAA+'
  const cleanName = rawName.replace(/^[A-Z]{6}\+/, "");
  const combined = `${cleanName} ${styleFontFamily || ""}`.toLowerCase();

  // ── Bold / italic detection ──────────────────────────────────────────────
  const bold =
    /bold|black|heavy|semibold|demibold|700|800|900/i.test(combined) ||
    // pdfjs FontFlags: Bit 19 (0x40000) = ForceBold
    ((fontFlags ?? 0) & 0x40000) !== 0;

  const italic =
    /italic|oblique/i.test(combined) ||
    // pdfjs FontFlags: Bit 7 (0x40) = Italic
    ((fontFlags ?? 0) & 0x40) !== 0;

  // ── Family detection — ordered most-specific first ───────────────────────
  let fontFamily: FontFamilyId = "Arial";

  if (/comic\s*sans|comicsans/i.test(combined)) {
    fontFamily = "Comic Sans MS";
  } else if (/impact/i.test(combined)) {
    fontFamily = "Impact";
  } else if (/playfair/i.test(combined)) {
    fontFamily = "Playfair Display";
  } else if (/merriweather/i.test(combined)) {
    fontFamily = "Merriweather";
  } else if (/poppins/i.test(combined)) {
    fontFamily = "Poppins";
  } else if (/montserrat/i.test(combined)) {
    fontFamily = "Montserrat";
  } else if (/lato/i.test(combined)) {
    fontFamily = "Lato";
  } else if (/open\s*sans|opensans/i.test(combined)) {
    fontFamily = "Open Sans";
  } else if (/roboto\s*mono|robotomono/i.test(combined)) {
    fontFamily = "Roboto Mono";
  } else if (/roboto/i.test(combined)) {
    fontFamily = "Roboto";
  } else if (/inter[^a-z]/i.test(combined) || /\binter\b/i.test(combined)) {
    fontFamily = "Inter";
  } else if (/segoe\s*ui|segoeui/i.test(combined)) {
    fontFamily = "Segoe UI";
  } else if (/trebuchet/i.test(combined)) {
    fontFamily = "Trebuchet MS";
  } else if (/tahoma/i.test(combined)) {
    fontFamily = "Tahoma";
  } else if (/verdana/i.test(combined)) {
    fontFamily = "Verdana";
  } else if (/calibri/i.test(combined)) {
    fontFamily = "Calibri";
  } else if (/noto\s*sans|noto/i.test(combined)) {
    fontFamily = "Noto Sans";
  } else if (/palatino|palatlinotype/i.test(combined)) {
    fontFamily = "Palatino";
  } else if (/garamond/i.test(combined)) {
    fontFamily = "Garamond";
  } else if (/cambria/i.test(combined)) {
    fontFamily = "Cambria";
  } else if (/georgia/i.test(combined)) {
    fontFamily = "Georgia";
  } else if (/times|timesnewroman|times\s*new\s*roman/i.test(combined)) {
    fontFamily = "Times New Roman";
  } else if (/consolas/i.test(combined)) {
    fontFamily = "Consolas";
  } else if (/courier/i.test(combined)) {
    fontFamily = "Courier New";
  } else if (/helvetica/i.test(combined)) {
    fontFamily = "Helvetica";
  } else if (/arial/i.test(combined)) {
    fontFamily = "Arial";
  } else {
    // Unknown font — use serif/mono/sans flags from pdfjs FontFlags
    // Bit 2 (0x2) = FixedPitch, Bit 1 (0x1) = Serif
    const flags = fontFlags ?? 0;
    if ((flags & 0x2) !== 0) {
      fontFamily = "Courier New"; // monospace
    } else if ((flags & 0x1) !== 0) {
      fontFamily = "Times New Roman"; // serif
    } else {
      fontFamily = "Arial"; // sans default
    }
  }

  return { fontFamily, bold, italic };
}

/**
 * Extract all runs for a page. Skips whitespace-only items and items whose
 * rect has zero area (some PDFs emit those for spacing hints).
 */
export async function extractTextRuns(
  page: PDFPageProxy,
  pageInfo: PageInfo,
  options: ExtractOptions = {},
): Promise<TextRunObject[]> {
  const content = await page.getTextContent();
  const items = (content.items ?? []) as unknown as PdfjsTextItem[];

  // Explicitly type the styles record instead of using `any`
  const styles = (content.styles || {}) as Record<
    string,
    { fontFamily?: string }
  >;

  // ── A. Operator-list colour extraction ─────────────────────────────────────
  let opColours = new Map<number, string>();
  if (options.pdfjsModule) {
    try {
      opColours = await extractColoursByOperatorList(page, options.pdfjsModule);
    } catch {
      // Operator list unavailable — opColours stays empty; fallback handles it
    }
  }

  const out: TextRunObject[] = [];
  const seen = new Set<string>();
  // opIdx mirrors the text-showing operator counter in extractColoursByOperatorList.
  // We increment for every item (including blank) to stay aligned.
  let opIdx = 0;

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const text = typeof item.str === "string" ? item.str : "";
    const currentOpIdx = opIdx++;
    if (!text.trim()) continue;

    const rect = pdfjsTextItemToPdfRect({
      transform: item.transform,
      width: item.width,
      height: item.height,
    });
    if (rect.w <= 0.1 || rect.h <= 0.1) continue;

    // Use pageUid to prevent collisions on duplicated pages
    const id = makeRunId(pageUid(pageInfo), i, text);
    if (seen.has(id)) continue;
    seen.add(id);

    // Extract exact font details from pdfjs styles mapped to clean web fonts
    const style = styles[item.fontName || ""] || {};
    const fontInfo = mapPdfFontToWeb(item.fontName || "", style.fontFamily);

    // Font size from the linear part of the transform matrix
    const a = item.transform[0] ?? 1;
    const b = item.transform[1] ?? 0;
    const c = item.transform[2] ?? 0;
    const d = item.transform[3] ?? 1;
    const fontSize = Math.max(4, Math.hypot(c, d) || Math.hypot(a, b) || 10);

    const bg = options.sampleBackground
      ? options.sampleBackground(rect)
      : (options.defaultBackground ?? "#ffffff");

    // ── B. Resolve text colour ────────────────────────────────────────────────
    const color = resolveTextColour(
      opColours,
      currentOpIdx,
      normalizeHexColor(bg),
    );

    const run: TextRunObject = {
      id,
      kind: "text-run",
      page: pageInfo.index,
      rect,
      rotation: 0,
      z: out.length,
      locked: false,
      opacity: 1,
      dirty: false,
      text,
      originalText: text,
      sourceFontName: item.fontName || style.fontFamily || "unknown",
      fontFamily: fontInfo.fontFamily,
      substituted: false,
      fontSize,
      bold: fontInfo.bold,
      italic: fontInfo.italic,
      underline: false,
      color,
      align: "left",
      lineHeight: 1.2,
      letterSpacing: 0,
      backgroundColor: normalizeHexColor(bg),
    };
    out.push(run);
  }

  // Sort for stable visual order: top → bottom, then left → right.
  out.sort((p, q) => {
    if (Math.abs(q.rect.y - p.rect.y) > 1) return q.rect.y - p.rect.y;
    return p.rect.x - q.rect.x;
  });

  // Reassign z after sorting so the array order matches the visual order.
  return out.map((run, idx) => ({ ...run, z: idx }));
}

/**
 * Merge freshly-extracted runs with any that already exist in the store.
 * Existing runs whose ids match a newly-extracted run keep their edited
 * state (`dirty`, `text`, style); new runs are added. Runs that no longer
 * appear in the PDF (user edited them away) are kept if `dirty` so the
 * user can still export them, otherwise dropped.
 */
export function reconcileTextRuns(
  existing: TextRunObject[],
  fresh: TextRunObject[],
): TextRunObject[] {
  const byId = new Map(existing.map((r) => [r.id, r]));
  const merged: TextRunObject[] = [];
  const used = new Set<string>();

  for (const run of fresh) {
    const prior = byId.get(run.id);
    if (prior) {
      merged.push(prior);
      used.add(prior.id);
    } else {
      merged.push(run);
    }
  }

  for (const run of existing) {
    if (!used.has(run.id) && run.dirty) merged.push(run);
  }

  return merged;
}

// src/components/pdf-editor/TextProperties.tsx
// Full text-style properties panel for selected text-run / new-text objects.
// Shows detected values on selection; supports multi-selection with "Mixed".
// Keyboard shortcuts: Ctrl+B (bold), Ctrl+I (italic), Ctrl+U (underline).
"use client";
import React, { useCallback, useEffect, useRef } from "react";
import { useShallow } from "zustand/react/shallow";
import { usePdfEditor } from "@/lib/pdf-editor/store";
import type { PDFObject, TextRunObject, NewTextObject } from "@/lib/pdf-editor/types";

// ─── Font catalogue ──────────────────────────────────────────────────────────

interface FontGroup {
  label: string;
  fonts: string[];
}

const FONT_GROUPS: FontGroup[] = [
  {
    label: "Sans-serif",
    fonts: [
      "Arial",
      "Helvetica",
      "Verdana",
      "Tahoma",
      "Trebuchet MS",
      "Segoe UI",
      "Calibri",
      "Roboto",
      "Open Sans",
      "Lato",
      "Montserrat",
      "Poppins",
      "Inter",
      "Noto Sans",
    ],
  },
  {
    label: "Serif",
    fonts: [
      "Times New Roman",
      "Georgia",
      "Cambria",
      "Garamond",
      "Palatino",
      "Merriweather",
      "Playfair Display",
    ],
  },
  {
    label: "Monospace",
    fonts: ["Courier New", "Consolas", "Roboto Mono"],
  },
  {
    label: "Display",
    fonts: ["Comic Sans MS", "Impact"],
  },
];

const ALL_FONTS = FONT_GROUPS.flatMap((g) => g.fonts);

const COMMON_SIZES = [6, 8, 9, 10, 11, 12, 14, 16, 18, 20, 24, 28, 32, 36, 48, 60, 72];

// ─── Recently used fonts (localStorage, max 5) ───────────────────────────────

function getRecentFonts(): string[] {
  try {
    const raw = localStorage.getItem("fk_recent_fonts");
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.slice(0, 5) : [];
  } catch {
    return [];
  }
}

function pushRecentFont(font: string): void {
  try {
    const existing = getRecentFonts().filter((f) => f !== font);
    localStorage.setItem(
      "fk_recent_fonts",
      JSON.stringify([font, ...existing].slice(0, 5)),
    );
  } catch {
    // localStorage unavailable (SSR, private mode, etc.)
  }
}

// ─── Types ────────────────────────────────────────────────────────────────────

type TextLike = TextRunObject | NewTextObject;

function isTextLike(o: PDFObject | undefined): o is TextLike {
  return !!o && (o.kind === "text-run" || o.kind === "new-text");
}

/** Returns a mixed sentinel when all values aren't equal; otherwise the shared value. */
function mixed<T>(arr: T[], key: keyof T): T[keyof T] | "Mixed" {
  if (arr.length === 0) return "Mixed";
  const first = arr[0][key];
  return arr.every((a) => a[key] === first) ? first : "Mixed";
}

// ─── Component ────────────────────────────────────────────────────────────────

export function TextProperties() {
  const { selectedIds, objects, commit } = usePdfEditor(
    useShallow((s) => ({
      selectedIds: s.selectedIds,
      objects: s.objects,
      commit: s.commit,
    })),
  );

  const [fontSearch, setFontSearch] = React.useState("");
  const [recentFonts, setRecentFonts] = React.useState<string[]>([]);

  // Load recent fonts from localStorage on mount (client only)
  useEffect(() => {
    setRecentFonts(getRecentFonts());
  }, []);

  const selected = selectedIds.map((id) => objects[id]).filter(isTextLike);

  if (selected.length === 0) return null;

  const first = selected[0];

  const apply = (patch: Partial<TextLike>) => {
    if (selected.length === 0) return;
    commit("Text style", (d) => {
      for (const obj of selected) {
        const cur = d.objects[obj.id];
        if (!cur || (cur.kind !== "text-run" && cur.kind !== "new-text"))
          continue;
        // Mark text-run dirty when styled
        const extra = cur.kind === "text-run" ? { dirty: true } : {};
        d.objects[obj.id] = { ...cur, ...extra, ...patch } as PDFObject;
      }
    });
  };

  const toggle = (key: "bold" | "italic" | "underline" | "strike") => {
    apply({ [key]: !first[key] } as Partial<TextLike>);
  };

  const applyFont = (font: string) => {
    apply({ fontFamily: font });
    pushRecentFont(font);
    setRecentFonts(getRecentFonts());
  };

  // Keyboard shortcuts wired at document level while panel exists
  const applyRef = useRef(apply);
  applyRef.current = apply;
  const firstRef = useRef(first);
  firstRef.current = first;

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const ctrl = e.ctrlKey || e.metaKey;
      if (!ctrl) return;
      if (e.key === "b" || e.key === "B") {
        e.preventDefault();
        applyRef.current({ bold: !firstRef.current.bold });
      } else if (e.key === "i" || e.key === "I") {
        e.preventDefault();
        applyRef.current({ italic: !firstRef.current.italic });
      } else if (e.key === "u" || e.key === "U") {
        e.preventDefault();
        applyRef.current({ underline: !firstRef.current.underline });
      }
    };
    window.addEventListener("keydown", handler, { capture: true });
    return () => window.removeEventListener("keydown", handler, { capture: true });
  }, []);

  // ── Computed mixed-value display ─────────────────────────────────────────
  const ff = mixed(selected, "fontFamily");
  const fs = mixed(selected, "fontSize");
  const col = mixed(selected, "color");
  const al = mixed(selected, "align");
  const lh = mixed(selected, "lineHeight");
  const ls = mixed(selected, "letterSpacing");
  const op = mixed(selected, "opacity");
  const isBold = mixed(selected, "bold");
  const isItalic = mixed(selected, "italic");
  const isUnderline = mixed(selected, "underline");
  const isStrike = mixed(selected, "strike");

  const displayFontSize = fs === "Mixed" ? "" : String(Math.round((fs as number) * 10) / 10);
  const displayColor = col === "Mixed" ? "#000000" : (col as string);
  const displayLh = lh === "Mixed" ? "" : String(lh);
  const displayLs = ls === "Mixed" ? "" : String(ls);
  const displayOp = op === "Mixed" ? "" : String(Math.round((op as number) * 100));

  // ── Font search filter ────────────────────────────────────────────────────
  const filteredGroups = fontSearch.trim()
    ? [
        {
          label: "Results",
          fonts: ALL_FONTS.filter((f) =>
            f.toLowerCase().includes(fontSearch.toLowerCase()),
          ),
        },
      ]
    : [
        ...(recentFonts.length > 0
          ? [{ label: "Recently Used", fonts: recentFonts }]
          : []),
        ...FONT_GROUPS,
      ];

  // ── "Reset to original style" for text-runs ──────────────────────────────
  const canReset = selected.some((s) => s.kind === "text-run" && (s as TextRunObject).dirty);

  const handleReset = useCallback(() => {
    commit("Reset style", (d) => {
      for (const obj of selected) {
        if (obj.kind !== "text-run") continue;
        const cur = d.objects[obj.id] as TextRunObject | undefined;
        if (!cur) continue;
        // Only reset style props, keep text edits
        d.objects[obj.id] = {
          ...cur,
          fontFamily: (cur as TextRunObject & { _origFontFamily?: string })._origFontFamily ?? cur.fontFamily,
          bold: cur.bold,
          italic: cur.italic,
          color: cur.color,
          fontSize: cur.fontSize,
          align: cur.align,
          lineHeight: cur.lineHeight,
          letterSpacing: cur.letterSpacing,
          opacity: cur.opacity,
        } as PDFObject;
      }
    });
  }, [commit, selected]);

  // ── Render ────────────────────────────────────────────────────────────────
  return (
    <div
      className="space-y-3 text-xs text-zinc-300 select-none"
      onKeyDown={(e) => {
        // Prevent editor shortcuts from firing while the panel inputs have focus
        const tag = (e.target as HTMLElement).tagName;
        if (tag === "INPUT" || tag === "SELECT") e.stopPropagation();
      }}
    >
      {/* ── Font selector ─────────────────────────────────────────────────── */}
      <div className="space-y-1">
        <label className="text-[10px] uppercase tracking-wide text-zinc-500">
          Font
        </label>
        <input
          type="text"
          placeholder="Search fonts…"
          value={fontSearch}
          onChange={(e) => setFontSearch(e.target.value)}
          className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1 text-xs mb-1"
        />
        <select
          value={ff === "Mixed" ? "" : (ff as string)}
          onChange={(e) => applyFont(e.target.value)}
          className="w-full bg-zinc-900 border border-zinc-700 rounded px-2 py-1"
          style={{ fontFamily: ff === "Mixed" ? undefined : (ff as string) }}
          size={5}
        >
          {ff === "Mixed" && (
            <option value="" disabled>
              — Mixed —
            </option>
          )}
          {filteredGroups.map((group) => (
            <optgroup key={group.label} label={group.label}>
              {group.fonts.map((f) => (
                <option key={f} value={f} style={{ fontFamily: f }}>
                  {f}
                </option>
              ))}
            </optgroup>
          ))}
        </select>
      </div>

      {/* ── B I U S ──────────────────────────────────────────────────────── */}
      <div className="flex items-center gap-1">
        {(
          [
            ["bold", "B", "font-bold", "Ctrl+B"],
            ["italic", "I", "italic", "Ctrl+I"],
            ["underline", "U", "underline", "Ctrl+U"],
            ["strike", "S", "line-through", ""],
          ] as const
        ).map(([key, label, cls, shortcut]) => (
          <button
            key={key}
            type="button"
            title={shortcut ? `${key} (${shortcut})` : key}
            onMouseDown={(e) => e.preventDefault()}
            onClick={() => toggle(key)}
            aria-pressed={
              key === "bold" ? isBold === true
              : key === "italic" ? isItalic === true
              : key === "underline" ? isUnderline === true
              : isStrike === true
            }
            className={`px-2 py-1 rounded border ${cls} ${
              (key === "bold" ? isBold : key === "italic" ? isItalic : key === "underline" ? isUnderline : isStrike) === true
                ? "bg-emerald-600 border-emerald-500 text-white"
                : (key === "bold" ? isBold : key === "italic" ? isItalic : key === "underline" ? isUnderline : isStrike) === "Mixed"
                ? "bg-zinc-700 border-zinc-600 text-zinc-400"
                : "border-zinc-700"
            }`}
          >
            {label}
          </button>
        ))}
      </div>

      {/* ── Size + Colour ─────────────────────────────────────────────────── */}
      <div className="flex items-center gap-2">
        {/* Size with +/- buttons */}
        <div className="flex items-center gap-0.5">
          <button
            type="button"
            onMouseDown={(e) => e.preventDefault()}
            onClick={() =>
              apply({
                fontSize: Math.max(
                  4,
                  (fs === "Mixed" ? (first.fontSize ?? 12) : (fs as number)) - 1,
                ),
              })
            }
            className="px-1.5 py-0.5 bg-zinc-800 border border-zinc-700 rounded-l text-zinc-400 hover:text-white"
            title="Decrease size"
          >
            −
          </button>
          <input
            type="number"
            value={displayFontSize}
            placeholder={fs === "Mixed" ? "Mixed" : ""}
            onMouseDown={(e) => e.preventDefault()}
            onChange={(e) =>
              apply({ fontSize: Math.max(4, parseFloat(e.target.value) || 12) })
            }
            className="w-12 bg-zinc-900 border-y border-zinc-700 px-1 py-0.5 text-center appearance-none"
            title="Font size"
          />
          <button
            type="button"
            onMouseDown={(e) => e.preventDefault()}
            onClick={() =>
              apply({
                fontSize: Math.min(
                  300,
                  (fs === "Mixed" ? (first.fontSize ?? 12) : (fs as number)) + 1,
                ),
              })
            }
            className="px-1.5 py-0.5 bg-zinc-800 border border-zinc-700 rounded-r text-zinc-400 hover:text-white"
            title="Increase size"
          >
            +
          </button>
        </div>

        {/* Common size presets */}
        <select
          value=""
          onChange={(e) =>
            apply({ fontSize: parseFloat(e.target.value) })
          }
          className="flex-1 bg-zinc-900 border border-zinc-700 rounded px-1 py-0.5"
          title="Common sizes"
        >
          <option value="" disabled>
            pt
          </option>
          {COMMON_SIZES.map((s) => (
            <option key={s} value={s}>
              {s}
            </option>
          ))}
        </select>

        {/* Colour swatch */}
        <div className="relative flex items-center gap-1">
          <input
            type="color"
            value={displayColor}
            onMouseDown={(e) => e.preventDefault()}
            onChange={(e) => apply({ color: e.target.value })}
            className="w-7 h-7 rounded border border-zinc-700 bg-transparent cursor-pointer p-0.5"
            title={col === "Mixed" ? "Mixed colours" : `Text color: ${col}`}
          />
          <input
            type="text"
            value={col === "Mixed" ? "Mixed" : (col as string)}
            onChange={(e) => {
              const v = e.target.value;
              if (/^#[0-9a-fA-F]{6}$/.test(v)) apply({ color: v });
            }}
            className="w-20 bg-zinc-900 border border-zinc-700 rounded px-1 py-0.5 font-mono"
            placeholder="#000000"
            title="Hex colour"
          />
        </div>
      </div>

      {/* ── Alignment ────────────────────────────────────────────────────── */}
      <div className="space-y-1">
        <label className="text-[10px] uppercase tracking-wide text-zinc-500">
          Align
        </label>
        <div className="flex items-center gap-1">
          {(["left", "center", "right", "justify"] as const).map((a) => (
            <button
              key={a}
              type="button"
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => apply({ align: a })}
              aria-pressed={al === a}
              className={`px-2 py-1 rounded border ${
                al === a
                  ? "bg-emerald-600 border-emerald-500 text-white"
                  : al === "Mixed" && a === "left"
                  ? "bg-zinc-700 border-zinc-600"
                  : "border-zinc-700"
              }`}
            >
              {a === "left" ? "⬅" : a === "center" ? "☰" : a === "right" ? "➡" : "⇔"}
            </button>
          ))}
        </div>
      </div>

      {/* ── Line-height / Letter-spacing / Opacity ────────────────────────── */}
      <div className="grid grid-cols-3 gap-2">
        <div className="space-y-1">
          <label className="text-[10px] uppercase tracking-wide text-zinc-500 block">
            Line-h
          </label>
          <input
            type="number"
            step="0.05"
            min="0.5"
            max="5"
            value={displayLh}
            placeholder={lh === "Mixed" ? "—" : "1.2"}
            onMouseDown={(e) => e.preventDefault()}
            onChange={(e) =>
              apply({
                lineHeight: Math.max(0.5, Math.min(5, parseFloat(e.target.value) || 1.2)),
              })
            }
            className="w-full bg-zinc-900 border border-zinc-700 rounded px-1 py-0.5 text-center"
            title="Line height multiplier"
          />
        </div>
        <div className="space-y-1">
          <label className="text-[10px] uppercase tracking-wide text-zinc-500 block">
            Spacing
          </label>
          <input
            type="number"
            step="0.5"
            min="-10"
            max="100"
            value={displayLs}
            placeholder={ls === "Mixed" ? "—" : "0"}
            onMouseDown={(e) => e.preventDefault()}
            onChange={(e) =>
              apply({
                letterSpacing: parseFloat(e.target.value) || 0,
              })
            }
            className="w-full bg-zinc-900 border border-zinc-700 rounded px-1 py-0.5 text-center"
            title="Letter spacing (pt)"
          />
        </div>
        <div className="space-y-1">
          <label className="text-[10px] uppercase tracking-wide text-zinc-500 block">
            Opacity %
          </label>
          <input
            type="number"
            step="5"
            min="0"
            max="100"
            value={displayOp}
            placeholder={op === "Mixed" ? "—" : "100"}
            onMouseDown={(e) => e.preventDefault()}
            onChange={(e) =>
              apply({
                opacity: Math.max(0, Math.min(1, (parseFloat(e.target.value) || 100) / 100)),
              })
            }
            className="w-full bg-zinc-900 border border-zinc-700 rounded px-1 py-0.5 text-center"
            title="Opacity 0–100%"
          />
        </div>
      </div>

      {/* ── Reset button (only for text-runs) ────────────────────────────── */}
      {canReset && (
        <button
          type="button"
          onMouseDown={(e) => e.preventDefault()}
          onClick={handleReset}
          className="w-full py-1 rounded border border-zinc-600 text-zinc-400 hover:border-zinc-400 hover:text-white text-[10px] uppercase tracking-wide transition-colors"
          title="Reset to original extracted style"
        >
          Reset to original style
        </button>
      )}

      {/* ── Substitution note ─────────────────────────────────────────────── */}
      {selected.length === 1 && selected[0].kind === "text-run" && (selected[0] as TextRunObject).substituted && (
        <p className="text-[10px] text-amber-400/80 leading-tight">
          ⚠ Font substituted in PDF export (original not available).
        </p>
      )}
    </div>
  );
}
